insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('gudrunschdrossn', 'Gudrunschdrossn', '', '', '', '', 'Gudrunstraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die in Ost-West-Richtung von [[Simmering]] bis zum [[Matzleinsdorfer]] Platz verläuft\""}, {"kategorie": "", "text": "Die Gudrunstraße wurde 1875 nach der Sagengestalt Gudrun aus der nordischen und germanischen Mythologie benannt. Gudrun ist die Heldin in der gleichnamigen altnordischen Gudrun-Saga sowie in der mittelhochdeutschen Gudrunlied-Dichtung, die im 13. Jahrhundert entstand"}, {"kategorie": "", "text": "Entlang der Gudrunstraße finden sich eine Vielzahl von Wohngebäuden, Geschäften, Restaurants und öffentlichen Einrichtungen wie Schulen und Kindergärten. Die Straße liegt in einem lebhaften Teil von Favoriten, das als einer der bevölkerungsreichsten Bezirke Wiens eine Mischung aus traditionellen Arbeiterwohnungen und modernen Wohnbauten aufweist."}]'::jsonb, ''),
  ('geislbeagschdrossn', 'Geislbeagschdrossn', '', '', '', '', 'Geiselbergstraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 11. Wiener Gemeindebezirk ([[Simmering]]), die eine bedeutende Ost-West-Verbindung innerhalb des Bezirks darstellt\""}, {"kategorie": "", "text": "Die Straße liegt im nördlichen Teil von [[Simmering]] und ist sowohl für den Individualverkehr als auch für den öffentlichen Verkehr eine zentrale Verkehrsader"}, {"kategorie": "", "text": "Die Geiselbergstraße ist nach dem Geiselberg benannt, einer leichten Anhöhe in der Umgebung von Simmering. Der Name „Geiselberg“ stammt vermutlich von dem mittelhochdeutschen Wort „Gisel“ (Geisel, also Pfand oder Bürge) ab und könnte auf alte Rechts- oder Pfandsysteme hindeuten, die mit der Region in Verbindung standen"}, {"kategorie": "", "text": "Die Geiselbergstraße stellt eine Verlängerung der [[Gudrunstraße]] nach Osten hin dar und endet nahe der [[Simmeringer]] Hauptstraße, einer der Hauptverkehrsachsen des Bezirks"}, {"kategorie": "", "text": "Die Straße führt durch ein gemischtes Wohn- und Gewerbegebiet und verbindet die Wohnviertel mit den industriellen und infrastrukturellen Teilen Simmerings."}]'::jsonb, ''),
  ('ghegaschdrossn', 'Ghegaschdrossn', '', '', '', '', 'Ghegastraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 3. Wiener Gemeindebezirk ([[Landstraße]]), die nach dem österreichischen Ingenieur und Eisenbahnpionier Carl Ritter von Ghega (1802–1860) benannt ist\""}, {"kategorie": "", "text": "Ghega war vor allem für den Bau der Semmeringbahn, der ersten Gebirgsbahn Europas, bekannt, die heute zum UNESCO-Weltkulturerbe gehört"}, {"kategorie": "", "text": "Sie befindet sich im Osten Wiens und verläuft im Bereich des [[Arsenals]], einem markanten historischen Militärkomplex in der Wiener Stadtlandschaft, der heute verschiedene Institutionen, Museen und Archive beherbergt, darunter das [[Heeresgeschichtliche]] Museum"}, {"kategorie": "", "text": "Die Ghegastraße ist durch ihre Nähe zum [[Hauptbahnhof]] und zu wichtigen Straßenbahn- und S-Bahn-Linien verkehrstechnisch gut angebunden. In der Nähe verkehren die Straßenbahnlinien 18 und D, die das Gebiet mit dem Stadtzentrum und anderen Bezirken verbinden. Zudem ist die Ghegastraße über die [[Südosttangente]] (A23) gut an das überregionale Straßennetz angebunden."}]'::jsonb, ''),
  ('hauffgossn', 'Hauffgossn', '', '', '', '', 'Hauffgasse', '[{"kategorie": "allg.", "text": "\"Straße im 11. Wiener Gemeindebezirk ([[Simmering]]), die nach dem deutschen Schriftsteller Wilhelm Hauff (1802–1827) benannt ist\""}, {"kategorie": "", "text": "Hauff war ein bedeutender Dichter und Schriftsteller der Romantik, der vor allem für seine Märchen und Novellen bekannt ist. Zu seinen bekanntesten Werken zählen \"Das Wirtshaus im Spessart\", \"Der kleine Muck\" und \"Kalif Storch\""}, {"kategorie": "", "text": "Zwischen 1942 und 1945 befand sich in der Hauffgasse ein Zwangsarbeiterlager. Dieses war - ebenso wie zahlreiche andere Lager auf Wiener Boden - einerseits ein Lager für Zwangsarbeiterinnen und Zwangsarbeiter, andererseits Sammellager für die zur Deportation vorgesehene Jüdinnen und Juden"}, {"kategorie": "", "text": "Heute verläuft die Hauffgasse durch ein dicht besiedeltes Wohn- und Geschäftsgebiet. Sie beginnt im Norden bei der [[Simmeringer]] Hauptstraße, einer der Hauptverkehrsachsen des Bezirks, und erstreckt sich in südöstlicher Richtung"}, {"kategorie": "", "text": "Die Hauffgasse befindet sich in einem urbanen Bereich und ist von Wohnhäusern, Schulen, und Geschäften umgeben."}]'::jsonb, ''),
  ('esteplotz', 'Esteplotz', '', '', '', '', 'Esteplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 3. Wiener Gemeindebezirk ([[Landstraße]]), der nach dem Adelsgeschlecht der Habsburg-Este benannt wurde, einer Linie der Habsburger, die ihren Ursprung in Italien hat\""}, {"kategorie": "", "text": "Insbesondere erinnert der Platz an den am 28. Juni 1914 in Sarajewo ermordeten Thronfolger Erzherzog Franz Ferdinand von Österreich-Este"}, {"kategorie": "", "text": "Die Umgebung des Esteplatzes ist von Wohngebäuden, Geschäften und Büros geprägt"}, {"kategorie": "", "text": "Der Platz liegt in einem Gebiet, das für seine gute Verkehrsanbindung und Nähe zu wichtigen städtischen Einrichtungen bekannt ist. In der unmittelbaren Umgebung befinden sich unter anderem die [[Landstraßer]] Hauptstraße, eine der Hauptverkehrsachsen des Bezirks, und der [[Bahnhof]] Wien Mitte, ein wichtiger Verkehrsknotenpunkt."}]'::jsonb, ''),
  ('oiszaeun', 'Oiszäun', '', '', '', '', 'Alszeile', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 17. Wiener Gemeindebezirk ([[Hernals]]), die sich über eine längere Strecke erstreckt und 1897 nach der entlang des Alser Bachs erbauten Häuserzeile benannt ist\""}, {"kategorie": "", "text": "Die Alszeile ist nach dem Bach \"Als\" benannt, der im [[Wienerwald]] entspringt, unterirdisch durch die Stadt fließt und nach 10,5km bei der Friedensbrücke in den [[Donaukanal]] mündet"}, {"kategorie": "", "text": "1840-1846 wurde die Als innerhalb des (wenig später geschaffenen) neunten Bezirks mit einem Kostenaufwand von mehr als einer Millionen Gulden eingewölbt"}, {"kategorie": "", "text": "Die Alszeile in [[Dornbach]] erstreckt sich über eine Länge von rund zwei Kilometern. Auffallend ist ihr – vor allem im unteren Teil – mehrheitlich schnurgerader Verlauf und die beidseitige Baumbepflanzung in der Gestalt einer Allee"}, {"kategorie": "", "text": "Die Alszeile verläuft durch ein überwiegend von Wohnhäusern und Villen geprägtes Gebiet, das zu den ruhigeren und gehobeneren Teilen des 17. Bezirks zählt. In unmittelbarer Umgebung befinden sich auch Schulen, Parks und Freizeiteinrichtungen."}]'::jsonb, ''),
  ('amundsnschdrossn', 'Amundsnschdrossn', '', '', '', '', 'Amundsenstraße', '[{"kategorie": "allg.", "text": "\"Straße im B10278Westen Wiens, die am Rande des [[Wienerwalds]] von [[Hadersdorf]] im 14. Wiener Gemeindebezirk ([[Penzing]]) bis nach [[Dornbach]] und [[Neuwaldegg]] im 17. Wiener Gemeindebezirk (Hernals) verläuft\""}, {"kategorie": "", "text": "Die Straße wurde nach Roald Amundsen (1872–1928) benannt, einem der bedeutendsten Entdecker des 20. Jahrhunderts. Amundsen ist vor allem für seine Antarktisexpedition bekannt, bei der er am 14. Dezember 1911 als erster Mensch den Südpol erreichte und damit den Wettlauf gegen den britischen Forscher Robert Falcon Scott gewann. Neben seinen Erfolgen in der Antarktis erforschte Amundsen auch die Nordwestpassage und war der erste Mensch, der sowohl den Nord- als auch den Südpol erreichte"}, {"kategorie": "", "text": "Die Amundsenstraße liegt in einem naturnahen Wohngebiet, das durch die Nähe zum Wienerwald geprägt ist, und bietet eine hohe Lebensqualität. Die gute Verkehrsanbindung und die ruhige Lage machen die Amundsenstraße zu einer attraktiven Wohngegend in einem der grüneren Bezirke Wiens"}]'::jsonb, ''),
  ('mauabochschdrossn', 'Mauabochschdrossn', '', '', '', '', 'Mauerbachstraße', '[{"kategorie": "allg.", "text": "\" wichtige Verkehrsstraße im 14. Wiener Gemeindebezirk, Penzing, die als Verbindungsstraße zwischen dem Wiener Stadtgebiet und der diederösterreichischen Gemeinde Mauerbach dient\""}, {"kategorie": "", "text": "Sie führt vom westlichen Stadtrand Wiens in den Wienerwald und stellt eine zentrale Verbindung zwischen der Stadt und dem umliegenden ländlichen Raum dar"}, {"kategorie": "", "text": "Der Straßenverlauf entspricht einem alten römerzeitlichen Weg, der über Tulbing ins Tullnerfeld führte (\"Bäckersteig\")"}, {"kategorie": "", "text": "Die Mauerbachstraße beginnt in [[Wien-Hadersdorf]] und verläuft in westlicher Richtung durch das westliche Wiener Stadtgebiet bis zur Stadtgrenze und weiter nach Mauerbach in Niederösterreich"}, {"kategorie": "", "text": "Sie durchquert dabei das landschaftlich reizvolle Gebiet des Wienerwalds und führt entlang von Wohngebieten, landwirtschaftlichen Flächen und Waldgebieten. Entlang der Straße finden sich auch einige Gasthöfe und Wanderwege, die zu den Erholungsgebieten im Wienerwald führen."}]'::jsonb, ''),
  ('sofiinoipn', 'Sofiinoipn', '', '', '', '', 'Sophienalpe', '[{"kategorie": "allg.", "text": "\"Hochplateau im [[Wienerwald]] (477 Meter) mit schöner Fernsicht zwischen [[Neuwaldegg]], [[Hainbach]], [[Hütteldorf]] und [[Mariabrunn]]\""}, {"kategorie": "", "text": "Anfang des 19. Jahrhunderts bestand in einem alten Gebäude eine Schäferei, aus der sich ein beliebtes Gasthaus entwickelte (Hotel-Restaurant nahe der Exelbergstraße, erbaut 1912-1915)"}, {"kategorie": "", "text": "Ihren Namen erhielt die Sophienalpe nach Erzherzogin Sophie, die gemeinsam mit ihrem Gatten Erzherzog Franz Karl (in der Nähe befindet sich die Franz-Karl-Aussicht) stets gern diesen Teil des Wienerwalds besuchte"}, {"kategorie": "", "text": "Ab 1874 führte aus dem Haltertal eine Standseilbahn zur Sophienalpe (Knöpferlbahn)"}, {"kategorie": "", "text": "Wo sich heute gegenüber dem Hotel der Heurigenschank befindet, stand früher ein großer Glaspavillon, der auf der Wiener Weltausstellung von 1873 verwendet worden war"}, {"kategorie": "", "text": "Die Sophienalpe hat als Erholungsort für die Wiener Bevölkerung eine lange Tradition. Sie bietet eine ruhige und idyllische Umgebung fernab des städtischen Trubels und hat sich als beliebtes Ziel für Tagesausflüge etabliert. Im Winter ist die Sophienalpe auch ein beliebter Ort für Schlittenfahren und Schneespaziergänge."}]'::jsonb, ''),
  ('haaboch', 'Haaboch', '', '', '', '', 'Hainbach', '[{"kategorie": "allg.", "text": "\"kleiner Bach im Westen von Wien und ein wichtiger Nebenfluss des [[Wienflusses]]\""}, {"kategorie": "", "text": "Er fließt durch den 14. Wiener Gemeindebezirk ([[Penzing]]), entspringt im [[Wienerwald]] und mündet in den [[Wienfluss]]"}, {"kategorie": "", "text": "Der Bach ist von landschaftlicher Bedeutung, da er Teil des natürlichen Gewässernetzes ist, das die grüne Umgebung Wiens prägt"}, {"kategorie": "", "text": "Der Name \"Hainbach\" stammt vermutlich vom Wort \"Hain\", was eine kleine Waldung oder einen bewaldeten Ort bezeichnet. Dies spiegelt die Lage des Baches wider, der durch bewaldete Gebiete des Wienerwalds fließt. Der Bach ist typisch für die kleinen Wasserläufe, die den Wienerwald durchziehen und zur Entwässerung des Gebiets beitragen."}]'::jsonb, ''),
  ('mariabrunn', 'Mariabrunn', '', '', '', '', 'Mariabrunn', '[{"kategorie": "allg.", "text": "\"historischer Ort im 14. Wiener Gemeindebezirk ([[Penzing]]), der für seine Wallfahrtskirche ([[Mariabrunner]] Kirche) und die gleichnamige Klosteranlage bekannt ist\""}, {"kategorie": "", "text": "Der Ort liegt am westlichen Stadtrand von Wien, am Rande des [[Wienerwalds]], und hat eine lange Tradition als Wallfahrtsort"}, {"kategorie": "", "text": "Namengebend ist eine Quelle, in der der Legende nach die heilige Gisela († 1033), Schwester Kaiser Heinrichs II. des Heiligen († 1024) und Gattin des ungarischen Königs Stephan des Heiligen († 1038), eine Marienstatue fand und durch Trinken des Wassers genas"}, {"kategorie": "", "text": "Neben seiner religiösen Bedeutung ist Mariabrunn auch ein Ausgangspunkt für Wanderungen im Wienerwald. Die malerische Umgebung und die Nähe zur Natur machen es zu einem beliebten Ziel für Spaziergänger und Naturfreunde. Besucher können die Wallfahrtskirche besichtigen, die heilende Quelle besuchen und die Ruhe der umliegenden Landschaft genießen."}]'::jsonb, ''),
  ('joonschdrossn', 'Joonschdrossn', '', '', '', '', 'Johnstraße', '[{"kategorie": "allg.", "text": "zentrale Verkehrsstraße im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]) und 14. Wiener Gemeindebezirk ([[Penzing]])"}, {"kategorie": "", "text": "Sie führt von der [[Felberstraße]] hinauf bis zur [[Oeverseestraße]] im Bereich der [[Schmelz]], einem großen Freizeit- und Erholungsgebiet, und spielt eine wichtige Rolle als Verbindungsstraße zwischen den Bezirken"}, {"kategorie": "", "text": "Sie ist nach dem österreichischen Feldmarschallleutnant Franz Xaver Freiherr von John (1782–1850) benannt, einem bedeutenden Militärführer in der [[Habsburgermonarchie]], der an den Napoleonischen Kriegen und den Revolutionskriegen in den Jahren 1848/1849 teilnahm und 1866 zum Kriegsminister ernannt wurde"}, {"kategorie": "", "text": "Die Johnstraße spielt eine wichtige Rolle als Verkehrsachse im 15. Wiener Bezirk und ist ein zentraler Teil des urbanen Lebens in [[Rudolfsheim-Fünfhaus]].  Sie ist sowohl für den Individualverkehr als auch für den öffentlichen Nahverkehr von großer Bedeutung."}]'::jsonb, ''),
  ('panikngossn', 'Panikngossn', '', '', '', '', 'Panikengasse', '[{"kategorie": "allg.", "text": "\"belebte Straße im 16. Wiener Bezirk ([[Ottakring]]), einem dicht besiedelten und urbanen Gebiet im Westen von Wien\""}, {"kategorie": "", "text": "Der Name Panikengasse leitet sich von der historischen Ried Paniken ab, einer landwirtschaftlichen Fläche (Ried), die einst zum Pfarracker von Ottakring gehörte"}, {"kategorie": "", "text": "Im 19. Jahrhundert wurde auf einem Teil dieser Ackerfläche die heute berühmte [[Ottakringer]] Brauerei errichtet, die ein wichtiges Wahrzeichen des Bezirks ist und eine zentrale Rolle in der Geschichte Ottakrings spielt"}, {"kategorie": "", "text": "Die Umgebung der Panikengasse ist typisch für Ottakring, geprägt von Wohngebäuden, die sowohl historische Zinshäuser als auch neuere Bauten umfassen. Die Nähe zur [[Ottakringer]] Brauerei, die eine der ältesten noch bestehenden Brauereien in Wien ist, gibt der Gegend eine besondere historische Bedeutung. In der Umgebung gibt es zahlreiche Geschäfte, Cafés und Lokale, die zu dem lebendigen, urbanen Charakter von Ottakring beitragen."}]'::jsonb, ''),
  ('grinzing', 'Grinzing', '', '', '', '', 'Grinzing', '[{"kategorie": "allg.", "text": "historischer Ortsteil im 19. Wiener Gemeindebezirk ([[Döbling]]), der für seine traditionelle Wiener [[Heurigenkultur]] und seine idyllische Lage am Rande des [[Wienerwalds]] bekannt ist"}, {"kategorie": "", "text": "Grinzing ist eine der berühmtesten Weinbaugegenden Wiens und zieht sowohl Einheimische als auch Touristen an, die das typische Wiener Flair und den Charme eines ländlichen Weindorfes genießen wollen"}, {"kategorie": "", "text": "Der Name „Grinzing“ bedeutet so viel wie „Siedlung am Gerinne“, also am Zusammenfluss von kleinen Bächen. Erstmals urkundlich erwähnt wurde Grinzing 1114 als Grinzigan"}, {"kategorie": "", "text": "Im Jahre 1892 wurde Grinzing schließlich bis zum Kamm des Wienerwalds mit weiteren acht Orten und Ortsteilen zum 19. Wiener Gemeindebezirk ([[Döbling]]) zusammengefasst und nach Wien eingemeindet"}, {"kategorie": "", "text": "Grinzing ist besonders bekannt für seine [[Heurigen]], traditionelle Wiener Weinstuben, in denen der junge Wein der Region ausgeschenkt wird. Viele der historischen Gebäude in Grinzing sind Heurigenlokale, die oft über gemütliche Innenhöfe und Weingärten verfügen. Besucher kommen hierher, um lokale Weine wie den [[Grünen]] Veltliner oder den [[Gemischten]] Satz zu genießen und dazu typische Wiener Spezialitäten wie [[Brettljause]], [[Schmalzbrot]], [[Liptauer]] oder Braten zu probieren"}, {"kategorie": "", "text": "Grinzing hat seinen dörflichen Charakter weitgehend bewahrt, mit engen Gassen, historischen Häusern und alten Winzerhöfen. Zu den Sehenswürdigkeiten des Ortes gehört die [[Pfarrkirche]] Grinzing, eine spätgotische Kirche, die im 14. Jahrhundert erbaut wurde. Sie ist ein Wahrzeichen des Orts und zeugt von der langen Geschichte Grinzings."}]'::jsonb, ''),
  ('heirignmusi', 'Heirignmusi', '', '', '', '', 'Heurigenmusik', '[{"kategorie": "allg.", "text": "\"traditionelle Musikform, die in den Wiener Heurigenlokalen gespielt wird und eng mit der Wiener Heurigenkultur verbunden ist\""}, {"kategorie": "", "text": "Die Tradition der Heurigenmusik reicht bis ins 19. Jahrhundert zurück, als die ersten Heurigenlokale eröffnet wurden. Besonders prägend war die Entwicklung der [[Schrammelmusik]] durch die Brüder Johann und Josef Schrammel in den 1870er-Jahren, die eine Form der Tanz- und Unterhaltungsmusik schufen, die stark mit der Heurigenkultur assoziiert wird"}, {"kategorie": "", "text": "Heurigenmusik umfasst eine Mischung aus Wiener Liedern, Volksmusik und Schrammelmusik. Diese Musikform ist charakteristisch für Wien und Umgebung und wird häufig live in den Heurigenlokalen gespielt"}, {"kategorie": "", "text": "Heurigenmusik ist nicht nur musikalische Untermalung, sondern ein wichtiger Teil der Wiener Lebenskultur. Sie spiegelt das Wiener Lebensgefühl wider, das geprägt ist von einer Mischung aus Melancholie, Humor und Leichtigkeit"}, {"kategorie": "", "text": "Das Herzstück der Heurigenmusik sind die [[Wiener]] Lieder. Sie handeln oft von den Themen Liebe, Wein, Natur und Heimat. Sie zeichnen sich durch eine melancholische, aber auch humorvolle Note aus. Bekannte Komponisten wie Johann Schrammel oder Ralph Benatzky prägten diesen Stil"}, {"kategorie": "", "text": "Typische Instrumente der Heurigenmusik sind Akkordeon, Zither, Geige, Gitarre und manchmal auch ein Kontrabass. Die Musik ist meist akustisch und in kleinen Besetzungen arrangiert, um die intime und gemütliche Atmosphäre des Heurigen zu unterstreichen."}]'::jsonb, ''),
  ('siivaring', 'Siivaring', '', '', '', '', 'Sievering', '[{"kategorie": "allg.", "text": "\"Stadtteil im 19. Wiener Gemeindebezirk ([[Döbling]]), der im nordwestlichen Teil Wiens liegt und für seine Weinbau-Tradition und [[Heurigenkultur]] bekannt ist\""}, {"kategorie": "", "text": "Ursprünglich war Sievering ein eigenständiges Dorf, das im Jahr 1892 nach Wien eingemeindet wurde. Heute gilt es als eine der exklusiveren Wohngegenden der Stadt, die durch ihre ruhige Lage, die Nähe zum Wienerwald und ihre Weinberge besticht"}, {"kategorie": "", "text": "Erstmals urkundlich erwähnt wurde Sievering im Jahr 1114 als Sufringen. Später wurde der Name schließlich über Suueringan und Sivring zu Sievering. Wohl bereits im Mittelalter wurde jedoch der Name dann auf den Hl. Severin (Severin von Noricum, † 482) bezogen, der im Frühmittelalter in der Umgebung missioniert haben soll. Das Wappen der Gemeinde zeigt den Heiligen und die [[Sieveringer]] Pfarrkirche ist ihm geweiht"}, {"kategorie": "", "text": "Sievering bestand ursprünglich aus zwei getrennten Dörfern, Ober-Sievering und Unter-Sievering, die später zusammengeführt und 1892 nach Wien eingemeindet wurden"}, {"kategorie": "", "text": "Der Weinbau ist seit Jahrhunderten das Herzstück von Sievering. Die sanften Hänge des [[Wienerwalds]] bieten ideale Bedingungen für den Anbau von Wein. Besonders bekannt sind die Weißweine der Region, darunter der Wiener [[Gemischte]] Satz, ein traditioneller Wein, der in Wien einen besonderen Stellenwert hat"}, {"kategorie": "", "text": "Die [[Heurigenlokale]] in Sievering sind typisch für die Wiener [[Weinbaukultur]] und ziehen sowohl Einheimische als auch Touristen an, die den jungen Wein und traditionelle Wiener Gerichte in einer gemütlichen, ländlichen Atmosphäre genießen möchten. Diese Lokale sind oft in alten Winzerhöfen untergebracht und bieten einen Einblick in das historische und kulturelle Erbe der Region"}, {"kategorie": "", "text": "Sievering ist aber auch bekannt für seine Villengebiete und gepflegten Wohnhäuser, die den Stadtteil zu einer exklusiven Wohngegend machen. Die Mischung aus historischen Winzerhäusern, Villen und moderner Architektur verleiht Sievering seinen besonderen Charme. Es ist ein Stadtteil, der städtische und ländliche Lebensweisen miteinander verbindet und eine hohe Lebensqualität bietet."}]'::jsonb, ''),
  ('nussduaf', 'Nussduaf', '', '', '', '', 'Nussdorf', '[{"kategorie": "", "text": "Der Name Nussdorf leitet sich von „Nuzdorf“ ab, was so viel wie „Nussdorf“ bedeutet und auf die Nussbäume hinweist, die früher in dieser Region in großer Zahl standen. Noch Anfang des 19. Jahrhunderts bestanden im Ort zahlreiche Nussbaumalleen"}, {"kategorie": "", "text": "Erstmals urkundlich erwähnt wurde Nussdorf im 12. Jahrhundert, als es ein kleines Bauerndorf am Rand von Wien war. Im Mittelalter entwickelte sich der Ort zu einem wichtigen Weinbaugebiet, das bis heute eng mit der [[Wiener]] Heurigenkultur verbunden ist"}, {"kategorie": "", "text": "1861 wurde die Nussdorfer Wehr- und Schleusenanlage ([[Schleuse]] Nussdorf) gebaut, um den [[Donaukanal]] vor Hochwasser zu schützen, was die Entwicklung des Ortes weiter vorantrieb. 1892 wurde Nussdorf zusammen mit anderen Vororten nach Wien eingemeindet und ist seither Teil des Bezirks Döbling"}, {"kategorie": "", "text": "Nussdorf hat seinen dörflichen Charme weitgehend bewahrt und ist für seine Mischung aus historischen Gebäuden, Winzerhöfen und modernen Villen bekannt. Viele der alten Winzerhäuser und engen Gassen sind erhalten geblieben und verleihen dem Stadtteil ein authentisches und romantisches Ambiente"}]'::jsonb, ''),
  ('heilignschdaedtaschdrossn', 'Heilignschdädtaschdrossn', '', '', '', '', 'Heiligenstädter Straße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 19. Wiener Gemeindebezirk ([[Döbling]]), die sich über eine lange Strecke vom Wiener Stadtteil [[Heiligenstadt]] in Richtung des nördlichen Wiener Umlands erstreckt\""}, {"kategorie": "", "text": "Sie verläuft entlang des [[Donaukanals]] und ist eine zentrale Verbindungsstraße zwischen den inneren Bezirken Wiens und den nördlichen Stadtteilen sowie dem Wiener Umland"}, {"kategorie": "", "text": "Die Heiligenstädter Straße ist nach dem Wiener Stadtteil Heiligenstadt benannt, einem der ältesten Ortsteile im 19. Bezirk, dessen Geschichte bis in die Römerzeit zurückreicht. Heiligenstadt war bis zur Eingemeindung im Jahr 1892 eine eigenständige Gemeinde und ist heute ein wichtiger Bestandteil von Döbling"}, {"kategorie": "", "text": "Am nördlichen Ende der Straße befindet sich die Verkehrsstation Heiligenstadt, die ein wichtiger Verkehrsknotenpunkt für die Wiener [[S-Bahn]], die U-Bahn-Linie U4 und zahlreiche Buslinien ist. Die Nähe zur Donauufer-Autobahn (A22) macht die Heiligenstädter Straße auch für den Autoverkehr von zentraler Bedeutung"}]'::jsonb, ''),
  ('heilignschdodt', 'Heilignschdodt', '', '', '', '', 'Heiligenstadt', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 19. Wiener Gemeindebezirk ([[Döbling]]), der am nördlichen Stadtrand von Wien liegt\""}, {"kategorie": "", "text": "Es gehört zu den ältesten besiedelten Gebieten d+B10299er Stadt und hat eine lange Geschichte, die bis in die Römerzeit zurückreicht"}, {"kategorie": "", "text": "Der Name Heiligenstadt leitet sich von \"heilige Stätte\" ab und deutet auf die religiöse Bedeutung des Ortes in früheren Jahrhunderten hin"}, {"kategorie": "", "text": "Heiligenstadt war ursprünglich eine römische Siedlung, die den Namen \"Villa Sancta\" trug. Aus dieser römischen Siedlung entwickelte sich im Laufe des Mittelalters ein Dorf mit religiöser Bedeutung, das später zu einem der wichtigsten Vororte Wiens wurde. Heiligenstadt wurde im Jahr 1892 zusammen mit anderen Vororten nach Wien eingemeindet und ist seither Teil des 19. Bezirks"}, {"kategorie": "", "text": "Eine der bekanntesten historischen Persönlichkeiten, die mit Heiligenstadt in Verbindung gebracht werden, ist Ludwig van Beethoven. Der berühmte Komponist lebte hier zeitweise und verfasste 1802 das Heiligenstädter Testament, einen bewegenden Brief, in dem er über seine fortschreitende Taubheit und seine Lebenskrise schrieb. Heute erinnert das Beethoven Museum in Heiligenstadt an seinen Aufenthalt in diesem Stadtteil"}, {"kategorie": "", "text": "Heiligenstadt liegt am Fuß des [[Kahlenbergs]] und des [[Leopoldsbergs]], zwei der bekanntesten Erhebungen des Wienerwalds. Diese Hügel sind Teil des Wiener Weinbaugebiets, das für seine [[Heurigenkultur]] bekannt ist"}]'::jsonb, ''),
  ('zaunrodbaunschdrossn', 'Zaunrodbaunschdrossn', '', '', '', '', 'Zahnradbahnstraße', '[{"kategorie": "allg.", "text": "\"Straße im 19. Wiener Gemeindebezirk ([[Döbling]]), die ihren Namen von der ehemaligen Wiener Zahnradbahn erhalten hat\""}, {"kategorie": "", "text": "Diese Bahn führte vom Stadtteil [[Nussdorf]] hinauf auf den [[Kahlenberg]], einen der bekanntesten Aussichtspunkte Wiens. Die Zahnradbahnstraße verläuft entlang der Strecke, auf der einst die historische Zahnradbahn fuhr, und verbindet den unteren Teil von Döbling mit den höher gelegenen, naturnahen Bereichen des [[Wienerwalds]]"}, {"kategorie": "", "text": "Die [[Wiener]] Zahnradbahn wurde im Jahr 1874 eröffnet und war die erste ihrer Art in Wien. Die Bahn wurde zunächst als Dampfzahnradbahn betrieben, später wurde über eine mögliche Elektrifizierung nachgedacht. In den 1920er-Jahren wurde der Betrieb jedoch eingestellt, und die Zahnradbahnstrecke verschwand. Die Zahnradbahnstraße erinnert heute an diese historische Bahnverbindung"}, {"kategorie": "", "text": "Die Zahnradbahnstraße liegt in einem Wohngebiet, das durch seine ruhige, grüne Lage und seine exklusive Bebauung gekennzeichnet ist. Die Nähe zum Wienerwald und zu beliebten Ausflugszielen wie dem [[Kahlenberg]] und dem [[Leopoldsberg]] macht die Straße zu einem attraktiven Wohnort."}]'::jsonb, ''),
  ('probusgossn', 'Probusgossn', '', '', '', '', 'Probusgasse', '[{"kategorie": "allg.", "text": "\"historische Straße im 19. Wiener Gemeindebezirk ([[Döbling]]), genauer im Stadtteil [[Nussdorf]]\""}, {"kategorie": "", "text": "Die Probusgasse wurde nach dem römischen Kaiser Marcus Aurelius Probus (232–282 n. Chr.) benannt, der sich durch seine Förderung des Weinbaus im damaligen römischen Reich einen Namen gemacht hat"}, {"kategorie": "", "text": "Die Probusgasse spiegelt die Geschichte Wiens und seiner Weinbautradition wider. Sie liegt in einem der ältesten und bedeutendsten Weinanbaugebiete der Stadt, das sich entlang der Hänge des [[Kahlenbergs]] und [[Leopoldsbergs]] erstreckt"}, {"kategorie": "", "text": "Ein herausragendes historisches Gebäude in der Probusgasse ist das sogenannte Beethovenhaus (Probusgasse 6), in dem der weltberühmte Komponist Ludwig van Beethoven im Jahr 1802 während seines Aufenthalts in Wien lebte. Beethoven zog sich in diese ruhige Umgebung zurück, um sich von seiner beginnenden Taubheit zu erholen und arbeitete in dieser Zeit an wichtigen Werken"}, {"kategorie": "", "text": "Das Beethovenhaus ist heute ein Museum, das an Beethovens Zeit in Wien erinnert und Besuchern einen Einblick in sein Leben und Schaffen bietet. Hier soll Beethoven auch sein berühmtes Heiligenstädter Testament verfasst haben, ein ergreifender Brief, in dem er über seine Verzweiflung wegen seines fortschreitenden Gehörverlustes schrieb"}, {"kategorie": "", "text": "Die Probusgasse ist auch bekannt für ihre zahlreichen [[Heurigenlokale]] – traditionelle Wiener Weinschenken, in denen lokaler Wein und hausgemachte Spezialitäten serviert werden."}]'::jsonb, ''),
  ('laudongossn', 'Laudongossn', '', '', '', '', 'Laudongasse', '[{"kategorie": "allg.", "text": "bedeutende Straße im 8. Wiener Gemeindebezirk ([[Josefstadt]])"}, {"kategorie": "", "text": "Sie erstreckt sich vom Hernalser Gürtel bis zur [[Schlösselgasse]] und verbindet somit zentrale Teile dieses dicht bebauten und historisch geprägten Bezirks"}, {"kategorie": "", "text": "Die Laudongasse ist nach dem österreichischen Feldmarschall Gideon Ernst von Laudon (1717–1790) benannt, der im 18. Jahrhundert eine zentrale Rolle in den österreichischen Militärkampagnen spielte und als einer der erfolgreichsten Kommandanten seiner Zeit gilt"}, {"kategorie": "hist.", "text": "Nach der Demolierung des [[Linienwalls]] entstand von der Schlösselgasse zum Hernalser Gürtel ein gerade ansteigender Gassenzug aus der Mitte des 17. Jahrhunderts mit geschlossener, viergeschossiger spätbiedermeierlich-frühhistoristischer Verbauung (unterbrochen durch den Barockkomplex des ehemaligen [[Schönbornpalais]])"}, {"kategorie": "", "text": "Die Laudongasse ist eine typische Wiener Straße mit einem reichen historischen Erbe und einem charmanten architektonischen Stadtbild. Als Teil der [[Josefstadt]] verkörpert die Laudongasse den traditionellen Charme Wiens, eingebettet in eine moderne und dynamische städtische Umgebung."}]'::jsonb, ''),
  ('liniinwoi', 'Liniinwoi', '', '', '', '', 'Linienwall', '[{"kategorie": "allg.", "text": "\"ehemalige Befestigungsanlage, die zwischen 1704 und 1706 um Wien errichtet wurde, um die Stadt vor Angriffen zu schützen\""}, {"kategorie": "", "text": "Der Linienwall diente insbesondere als Verteidigung gegen die Bedrohungen durch die Türkenkriege und später durch die Truppen des Spanischen Erbfolgekriegs"}, {"kategorie": "", "text": "Die Mauer verlief als äußerer Ring um das damalige Stadtgebiet Wiens, großteils entlang des heutigen [[Gürtels]], einer der wichtigsten Verkehrsstraßen Wiens"}, {"kategorie": "", "text": "Der Wall war rund 13 Kilometer lang und bestand aus einem Erdwall mit vorgelagertem Graben. Insgesamt gab es etwa 13 Durchlässe (die sogenannten Linien, wie zum Beispiel die Gumpendorfer Linie oder die Hernalser Linie)"}, {"kategorie": "", "text": "Neben der militärischen Schutzfunktion diente der Linienwall auch als Zollgrenze. Er wurde an bestimmten Durchgängen, sogenannten Linienämtern, durchbrochen, wo die Einfuhr von Waren kontrolliert und verzollt wurde. Dies führte zur Entstehung des Begriffs Liniengeld, eine Abgabe, die beim Passieren des Walls fällig wurde"}, {"kategorie": "", "text": "Mit der Entwicklung der Artillerie und der fortschreitenden Urbanisierung verlor der Linienwall seine militärische Bedeutung. Er war nicht mehr zeitgemäß, als Wien zu einer modernen Großstadt wuchs. Ab den 1850er-Jahren wurde der Wall allmählich abgetragen, um Platz für den Ausbau der Stadt zu schaffen."}]'::jsonb, ''),
  ('seidngossn', 'Seidngossn', '', '', '', '', 'Seidengasse', '[{"kategorie": "allg.", "text": "\"Straße im 7. Wiener Gemeindebezirk ([[Neubau]]), die sich vom Gürtel bis zur [[Hermannstraße]] erstreckt\""}, {"kategorie": "", "text": "Sie liegt in einem lebendigen Stadtteil, der vor allem für seine historische Bedeutung, seine Nähe zum Wiener Stadtzentrum und seine Entwicklung als Kunst- und Kulturviertel bekannt ist"}, {"kategorie": "", "text": "Die Seidengasse erhielt ihren Namen im Jahr 1862 und verweist auf die einst florierende Seidenindustrie in Wien, die vor allem im 18. und 19. Jahrhundert von großer Bedeutung war"}, {"kategorie": "", "text": "Wien war im 18. und 19. Jahrhundert ein Zentrum der Textil- und insbesondere der Seidenproduktion. Die Seidengasse, die in diesem Zusammenhang benannt wurde, erinnert an diese Zeit, als viele Wiener Handwerksbetriebe, darunter auch Seidenweber, in diesem Stadtgebiet ansässig waren"}, {"kategorie": "", "text": "Viele der in dieser Zeit errichteten Gebäude entlang der Seidengasse stammen aus der Gründerzeit und zeichnen sich durch ihren charakteristischen Wiener Baustil aus"}, {"kategorie": "", "text": "Im Laufe der Zeit hat sich die Seidengasse von einem Standort für handwerkliche Betriebe zu einer Wohn- und Geschäftsstraße entwickelt. Heute befinden sich in der Umgebung zahlreiche kleine Geschäfte, Cafés und Restaurants, die das multikulturelle und kreative Flair des Bezirks widerspiegeln."}]'::jsonb, ''),
  ('hermanngossn', 'Hermanngossn', '', '', '', '', 'Hermanngasse', '[{"kategorie": "allg.", "text": "kurze, aber historische Straße im Herzen des 7. Wiener Gemeindebezirks ([[Neubau]])"}, {"kategorie": "", "text": "Sie ist nach dem Kanzleidirektor des [[Schottenstifts]] und Schottenpriester Hermann Gaunersdorfer (* 1791, † 16. August 1844) benannt und hat eine reiche Geschichte, die eng mit der Entwicklung des Wiener Handwerks und der Industrialisierung im 18. und 19. Jahrhundert verknüpft ist"}, {"kategorie": "", "text": "Viele der Gebäude in der Hermanngasse stammen aus der [[Gründerzeit]], also aus dem späten 19. Jahrhundert, und besitzen die für Wien typischen Altbaufassaden mit Verzierungen und hohen Decken"}, {"kategorie": "", "text": "Die Bebauung ist kompakt, und die Hermanngasse repräsentiert den typischen städtischen Charakter des Bezirks Neubau, der als Wohn- und Geschäftsviertel florierte und floriert."}]'::jsonb, ''),
  ('schoenboanpark', 'Schönboanpark', '', '', '', '', 'Schönbornpark', '[{"kategorie": "allg.", "text": "öffentlicher Park im 8. Wiener Gemeindebezirk ([[Josefstadt]]). Er befindet sich in unmittelbarer Nähe des [[Palais]] Schönborn und hat eine enge historische Verbindung zu diesem Bauwerk, da er ursprünglich als Garten des Palais diente"}, {"kategorie": "", "text": "Der Park wurde im frühen 18. Jahrhundert als barocker Garten für das Palais Schönborn in der Laudongasse angelegt. Dieser Palais diente der Familie Schönborn als Sommerresidenz und befand sich damals am Rande der Stadt"}, {"kategorie": "", "text": "Zu den bekanntesten Mitgliedern der Familie zählt Friedrich Karl von Schönborn, der ab 1705 Reichsvizekanzler und von 1729 bis zu seinem Tode 1746 Fürstbischof von Würzburg und Bamberg war und anstelle des älteren Lusthauses 1706-1711 nach einem Entwurf Johann Lukas von Hildebrandts (1705/1706) durch dessen Bauführer Franz Jänggl ein Sommerpalais mit Front an der Laudongasse errichten und den Garten neu gestalten ließ"}, {"kategorie": "", "text": "Die Gartenanlage war ursprünglich im Stil eines französischen Barockgartens gestaltet, was typisch für die Adelsresidenzen der Zeit war. Solche Gärten zeichneten sich durch symmetrische Anordnung, akkurat geschnittene Hecken und Wege sowie Zierbeete aus"}, {"kategorie": "", "text": "Heute ist der Schönbornpark ein kleines, historisches Überbleibsel des einst prächtigen Barockgartens des Palais Schönborn. Er dient er als öffentlicher Park und bietet den Bewohnern Wiens einen ruhigen Rückzugsort im Herzen der Stadt. Seine historische Verbindung zum Palais Schönborn macht ihn zu einem bedeutenden Teil der Wiener Stadtgeschichte."}]'::jsonb, ''),
  ('woedmuseum', 'Wödmuseum', '', '', '', '', 'Weltmuseum', '[{"kategorie": "allg.", "text": "\"eines der bedeutendsten ethnologischen Museen Europas, das sich in der [[Wiener]] Hofburg befindet (auch bekannt als \"Völkerkundemuseum\" bzw. \"ethnographisches M;useum\")"}, {"kategorie": "", "text": "Es widmet sich der Erforschung und Präsentation von Kulturen und Gesellschaften aus aller Welt, insbesondere aus Afrika, Asien, Ozeanien und Amerika"}, {"kategorie": "", "text": "Das Museum beherbergt eine der größten Sammlungen ethnographischer Objekte in Österreich und vermittelt den Besuchern durch Ausstellungen, Forschung und Bildungsprogramme ein tiefes Verständnis für die kulturelle Vielfalt der Menschheit"}, {"kategorie": "", "text": "Das Weltmuseum Wien hat seine Wurzeln in der Kunst- und Wunderkammer der Habsburger, die im 16. Jahrhundert exotische Objekte aus fernen Ländern sammelten"}, {"kategorie": "", "text": "Ein wichtiger Wendepunkt war die wissenschaftliche Expedition des österreichischen Erzherzogs Ferdinand Maximilian in den 1850er Jahren, deren Funde den Grundstock für die ethnographische Sammlung bildeten"}, {"kategorie": "", "text": "1876 wurde das Völkerkundemuseum Wien offiziell gegründet, um die ethnographischen Bestände der Habsburger einem breiteren Publikum zugänglich zu machen"}, {"kategorie": "", "text": "2017 wurde das Museum nach einer umfassenden Modernisierung in Weltmuseum Wien umbenannt, um den heutigen, global ausgerichteten und interkulturellen Fokus des Museums zu betonen"}, {"kategorie": "", "text": "Das Weltmuseum Wien beherbergt über 400.000 ethnographische Objekte, darunter Kunstwerke, Alltagsgegenstände, religiöse Artefakte, Textilien und Fotografien. Die Sammlung umfasst Objekte aus der ganzen Welt und repräsentiert das kulturelle Erbe zahlreicher Gesellschaften"}, {"kategorie": "", "text": "Eines der bekanntesten und umstrittensten Objekte im Weltmuseum ist der sogenannte Federkopfschmuck des Montezuma, ein prachtvoller Kopfschmuck aus Mexiko, der der aztekischen Hochkultur zugeschrieben wird. Der Federkopfschmuck ist das einzige erhaltene Objekt seiner Art, weshalb Mexiko dessen Rückgabe fordert. Wissenschaftliche Untersuchungen durch Spezialisten beider Länder haben allerdings ergeben, dass die Federkrone einen Transport nicht unbeschadet überstehen würde, weshalb eine Rückkehr nach Mexiko sehr unwahrscheinlich ist."}]'::jsonb, ''),
  ('voikskundemuseum', 'Voikskundemuseum', '', '', '', '', 'Volkskundemuseum', '[{"kategorie": "allg.", "text": "\"eines der größten und bedeutendsten Museen für Volkskultur in Österreich. Es widmet sich der Erforschung, Sammlung und Ausstellung von Alltagskultur, Traditionen und Bräuchen vorwiegend aus dem österreichischen und europäischen Raum\""}, {"kategorie": "", "text": "Seit 1917 befindet sich das Volkskundemuseum im [[Palais]] Schönborn, einem barocken Stadtpalast im 8. Wiener Gemeindebezirk ([[Josefstadt]])"}, {"kategorie": "", "text": "Die Sammlung des Museums umfasst über 150.000 Objekte, darunter Textilien, Möbel, Keramik, Werkzeuge, Volkskunst, Feste und Bräuche sowie Fotografien und Dokumente"}, {"kategorie": "", "text": "Die Exponate stammen vorwiegend aus Österreich und den Nachbarländern wie Ungarn, Slowenien, der Slowakei und Tschechien, aber es gibt auch Stücke aus anderen Teilen Europas"}, {"kategorie": "", "text": "Besondere Bedeutung kommt der Sammlung von traditioneller Kleidung (Tracht) zu, die die Vielfalt der regionalen Mode und den sozialen Kontext zeigt. Außerdem dokumentiert das Museum den Wandel von Handwerksberufen, der Architektur von Bauernhöfen und das Brauchtum in den unterschiedlichen Regionen Österreichs"}, {"kategorie": "", "text": "Die Dauerausstellung des Volkskundemuseums bietet einen umfassenden Überblick über (i) traditionelle Feste und Bräuche (etwa Hochzeiten, Erntedankfeste und andere religiöse und saisonale Feiern), (ii) Alltagsleben und Arbeitswelten in ländlichen und städtischen Gemeinschaften vom 18. bis ins 20. Jahrhundert, sowie (iii) Volkskunst und künstlerische Ausdrucksformen, die im Kontext des ländlichen und bürgerlichen Lebens entstanden sind"}, {"kategorie": "", "text": "Der zum [[Palais]] Schönborn gehörende Garten, der [[Schönbornpark]], ist heute eine öffentliche Grünfläche. Ursprünglich als barocker Garten angelegt, wurde der Park im Laufe der Zeit zu einer lockeren, natürlichen Parklandschaft umgestaltet, die den Bewohnern des 8. Bezirks als Erholungsraum dient."}]'::jsonb, ''),
  ('sensngossn', 'Sensngossn', '', '', '', '', 'Sensengasse', '[{"kategorie": "allg.", "text": "\"Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die historisch und städtebaulich von Bedeutung ist\""}, {"kategorie": "", "text": "Sie befindet sich in der Nähe der Universitätskliniken und der medizinischen Fakultät der [[Universität]] Wien, weswegen sie in der Umgebung oft als Teil des medizinischen Zentrums Wiens betrachtet wird"}, {"kategorie": "", "text": "Die Gasse ist nach dem Hausschild, “Zur goldenen Sense”, benannt (Währinger Straße 33-35, erstmals erwähnt 1765). Hausschilder bildeten in der Stadt und in den Vorstädten bis zur Einführung der Konskriptionsnummern unter [[Maria]] Theresia (1771; Häusernummerierung) die einzige Möglichkeit zur Kennzeichnung von Häusern. Neben Straßen- und Gassennamen waren sie wichtige räumliche Orientierungspunkte"}, {"kategorie": "", "text": "Heute ist die Sensengasse Teil des medizinischen und wissenschaftlichen Zentrums Wiens. In der Umgebung befinden sich zahlreiche Einrichtungen, die mit dem Gesundheitssystem und der medizinischen Forschung verbunden sind, was sie zu einem bedeutenden Standort für die Stadt macht."}]'::jsonb, ''),
  ('gonzagagossn', 'Gonzagagossn', '', '', '', '', 'Gonzagagasse', '[{"kategorie": "allg.", "text": "\"exklusive Wohn- und Geschäftsstraße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die sich in einem historisch bedeutenden Teil Wiens befindet\""}, {"kategorie": "", "text": "Die Gonzagagasse verläuft in nordwestlicher Richtung und verbindet den [[Schottenring]] mit dem [[Morzinplatz]]"}, {"kategorie": "", "text": "Die Gonzagagasse wurde 1864 nach dem italienischen Adelsgeschlecht der Herzöge von Gonzaga benannt, deren Name mit der italienischen Stadt Mantua verbunden ist"}, {"kategorie": "", "text": "Die Gonzagas spielten im 16. und 17. Jahrhundert eine bedeutende Rolle in der europäischen Geschichte und pflegten enge Beziehungen zu den Habsburgern"}, {"kategorie": "", "text": "Die Benennung erfolgte in Anlehnung an Eleonora Gonzaga, die als Gemahlin von zwei Habsburger Kaisern (Ferdinand II. und Ferdinand III.) eine bedeutende Rolle am Wiener Hof spielte"}, {"kategorie": "", "text": "Die Gegend gehörte im Mittelalter zur Vorstadt vor dem [[Werdertor]], nach der [[Ersten]] Türkenbelagerung zum [[Glacis]] und wurde danach teilweise von Befestigungsanlagen beansprucht"}, {"kategorie": "", "text": "Die Gonzagagasse ist geprägt von repräsentativen Wohn- und Geschäftshäusern, die größtenteils im späten 19. Jahrhundert im Stil der Wiener Ringstraßenarchitektur erbaut wurden. Diese Gebäude zeichnen sich durch ihre prächtige Fassadengestaltung und die großflächigen Grundrisse aus, die auf den Wohlstand der damaligen Bewohner hinweisen"}, {"kategorie": "", "text": "Die Gebäude entlang der Gonzagagasse stammen überwiegend aus der Gründerzeit (spätes 19. Jahrhundert), einer Zeit intensiver städtebaulicher Entwicklung in Wien. Viele der Häuser sind heute renoviert und beherbergen luxuriöse Wohnungen, Büros und Geschäfte."}]'::jsonb, ''),
  ('josefsplotz', 'Josefsplotz', '', '', '', '', 'Josefsplatz', '[{"kategorie": "allg.", "text": "\"einer der prächtigsten Plätze Wiens, der durch seine klassizistische Architektur und seine historische Bedeutung beeindruckt\""}, {"kategorie": "", "text": "Er liegt im Herzen Wiens und ist Teil des [[Hofburg-Komplexes]], der jahrhundertelang als Residenz der [[Habsburger]] diente. Der Platz grenzt an den [[Michaelerplatz]] und den [[Heldenplatz]]"}, {"kategorie": "", "text": "In der Mitte des Platzes steht das Reiterdenkmal von Kaiser [[Joseph]] II., nach dem der Platz benannt ist. Die Bronzestatue zeigt Joseph II. in klassischer Reiterpose und wurde von Franz Anton Zauner gestaltet. Das Denkmal wurde 1807 enthüllt und erinnert an den Kaiser, der für seine weitreichenden Reformen bekannt ist"}, {"kategorie": "", "text": "Wichtige Gebäude am Josefsplatz sind die [[Österreichische]] Nationalbibliothek sowie das auf der gegenüber liegenden Seite befindliche [[Palais]] Pallavicini, ein prachtvolles klassizistisches Stadtpalais, das 1784 im Auftrag der Familie Pallavicini erbaut wurde. Es gilt als eines der schönsten Beispiele des [[Wiener]] Klassizismus."}]'::jsonb, ''),
  ('tiaknkriag', 'Tiaknkriag', '', '', '', '', 'Türkenkriege', '[{"kategorie": "allg.", "text": "\"zwei bedeutende militärische Konflikte, in denen das Osmanische Reich versuchte, Wien zu erobern\""}, {"kategorie": "", "text": "Diese Kriege fanden im Rahmen der Osmanisch-Habsburgischen Kriege statt und führten zu zwei großen Belagerungen Wiens: 1529 und 1683"}, {"kategorie": "", "text": "Beide Belagerungen waren Teil des jahrhundertelangen Konflikts zwischen dem [[Habsburgerreich]] und dem expandierenden Osmanischen Reich"}, {"kategorie": "", "text": "Nach der Eroberung Ungarns in der Schlacht von Mohács (1526), bei der die osmanischen Truppen unter Sultan Süleyman dem Prächtigen den ungarischen König Ludwig II. besiegten, geriet ein Großteil Ungarns unter osmanische Kontrolle"}, {"kategorie": "", "text": "à1. Türkenbelagerung: Im Jahr 1529 marschierte Sultan Süleyman der Prächtige mit einer großen Armee auf Wien zu und belagerte die Stadt. Die Osmanen hatten eine Armee von etwa 100.000 Mann, die Stadt selbst war jedoch schlecht auf die Belagerung vorbereitet. Trotz der Übermacht gelang es den Verteidigern unter Niklas Graf Salm, die Stadt erfolgreich zu verteidigen. Die osmanischen Truppen waren gezwungen, sich aufgrund von schlechtem Wetter und Versorgungsproblemen zurückzuziehen. Wien wurde somit vor der Eroberung bewahrt"}, {"kategorie": "", "text": "à2. Türkenbelagerung: Im 17. Jahrhundert befanden sich das Osmanische Reich und das Habsburgerreich erneut in Konflikten um die Vorherrschaft in Mitteleuropa. Unter Sultan Mehmed IV. planten die Osmanen einen erneuten Angriff auf Wien, um die habsburgische Kontrolle in Europa zu schwächen und das osmanische Territorium zu erweitern. Im Jahr 1683 rückten die osmanischen Truppen unter der Führung von Großwesir Kara Mustafa mit etwa 150.000 Soldaten gegen Wien vor und belagerten die Stadt im Sommer desselben Jahres. Wien stand unter der Verteidigung von [[Leopold]] I., dem Kaiser des Heiligen Römischen Reiches, und der Stadtkommandant war Ernst Rüdiger von Starhemberg. Die entscheidende Wende kam am 12. September 1683, als ein Entsatzheer unter der Führung des polnischen Königs Jan III. Sobieski und Truppen des Heiligen Römischen Reiches die Osmanen in der Schlacht am Kahlenberg besiegte. Diese Schlacht markierte einen bedeutenden Wendepunkt in den Türkenkriegen und beendete die osmanische Bedrohung für Wien."}]'::jsonb, ''),
  ('minoritnplotz', 'Minoritnplotz', '', '', '', '', 'Minoritenplatz', '[{"kategorie": "allg.", "text": "historisch und politisch bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), der sich in der Nähe der [[Wiener]] Hofburg befindet und von prunkvollen Palais und Regierungsgebäuden umgeben ist"}, {"kategorie": "", "text": "Der Minoritenplatz ist nach der [[Minoritenkirche]] benannt, einer der ältesten Kirchen Wiens, die um das Jahr 1224 gegründet wurde. Die Minoriten sind ein Bettelorden (Franziskaner), der sich in dieser Gegend niederließ"}, {"kategorie": "", "text": "Der Platz wurde bereits im Mittelalter angelegt, trägt seit 1786 seinen heutigen Namen, erhielt seine heutige Form und Bedeutung aber erst im Laufe des 18. und 19. Jahrhunderts (nach der Demolierung des Minoritenklosters [1892-1903]), als die umgebenden Gebäude errichtet wurden, darunter zahlreiche Paläste des Wiener Adels und Regierungsinstitutionen, darunter das [[Haus-]], Hof- und Staatsarchiv (Minoritenplatz 1), das [[Palais]] Dietrichstein (Minoritenplatz 3), das [[Palais]] Liechtenstein (Minoritenplatz 4), das [[Palais]] Starhemberg (Minoritenplatz 5), das [[Palais]] Niederösterreich (Minoritenplatz 7), das Bundesministerium für europäische und internationale Angelegenheiten (Minoritenplatz 8), sowie das Bundesministerium für Inneres (Minoritenplatz 9)."}]'::jsonb, ''),
  ('apostlgossn', 'Apostlgossn', '', '', '', '', 'Apostelgasse', '[{"kategorie": "allg.", "text": "\"historische Straße im 3. Wiener Gemeindebezirk ([[Landstraße]]) im Stadtteil [[Erdberg]]\""}, {"kategorie": "", "text": "Der Name der Gasse verweist auf die Apostel Petrus und Paulus, die als Namenspatrone der nahegelegenen \"Pfarrkirche St. Peter und Paul\" ([[Pfarrkirche]] Erdberg) verehrt werden"}, {"kategorie": "", "text": "Diese Kirche, die sich an der Adresse Apostelgasse 1 befindet, hat eine lange Geschichte, die bis ins 13. Jahrhundert zurückreicht. Der Bau, der den Heiligen Petrus und Paulus geweiht ist, wurde zwischen 1700 und 1723 im barock-klassizistischen Stil errichtet und steht heute unter Denkmalschutz"}, {"kategorie": "", "text": "Im Laufe der Jahre hat sich die Straße zu einer wichtigen Verbindung innerhalb Erdbergs entwickelt und ist zugleich ein Symbol für die historische und spirituelle Verankerung des Viertels"}, {"kategorie": "", "text": "Die Pfarrkirche, die über Jahrhunderte hinweg immer wieder ausgebaut und restauriert wurde, steht in engem Bezug zur Apostelgasse und trägt wesentlich zur Identität dieses Teils von Wien bei."}]'::jsonb, ''),
  ('hagnmuellagossn', 'Hagnmüllagossn', '', '', '', '', 'Hagenmüllergasse', '[{"kategorie": "allg.", "text": "\"Straße im 3. Wiener Gemeindebezirk ([[Landstraße]]), im Stadtteil [[Erdberg]]\""}, {"kategorie": "", "text": "Sie wurde 1874 nach Franz Joseph Freiherr von Haggenmüller zu Grienberg (1746–1824) benannt, einem Beamten und Herrschaftsbesitzer, der maßgebliche Verdienste für die Stadt Wien erbrachte"}, {"kategorie": "", "text": "Haggenmüller begann seine Karriere als Sekretär der niederösterreichischen Landesregierung und stieg später zum Regierungsrat und Kanzleidirektor beim Hofbauamt auf. 1781 erwarb er die Herrschaften [[Erdberg]] und [[Altlerchenfeld]], die er später an die [[Stadt]] Wien weiterverkaufte. Er wurde für seine Verdienste, insbesondere für seine Leistungen im Bereich der Stadtfinanzen, 1815 zum Ehrenbürger Wiens ernannt"}, {"kategorie": "", "text": "An der Hagenmüllergasse befindet sich auch die bedeutende städtische Wohnhausanlage [[Volkswohnhaus Hagenmüllergasse]], die 1927/1928 nach Plänen von Karl Dirnhuber erbaut wurde. Diese U-förmig angeordnete Wohnhausanlage mit ihrem begrünten Innenhof und zahlreichen Loggien und Balkonen galt als eines der modernsten Bauprojekte der 1920er Jahre und bot ursprünglich 131 bis 133 Wohnungen"}, {"kategorie": "", "text": "An Hausnummer 30 befindet sich das Gymnasium Hagenmüllergasse (auch bekannt als GRG3 Hagenmüllergasse). Das Schulgebäude, ein markanter Eckbau an der Drorygasse/Hagenmüllergasse, wurde zwischen 1909 und 1914 erbaut und im Laufe der Jahre mehrfach saniert und erweitert"}, {"kategorie": "", "text": "In seiner Geschichte spielte die Schule während des Ersten Weltkrieges eine besondere Rolle, als das neu errichtete Gebäude zunächst als Reservelazarett genutzt wurde. Trotz der Widrigkeiten in Kriegszeiten konnte der Schulbetrieb nach dem Krieg wieder aufgenommen werden"}, {"kategorie": "", "text": "Einer der bekanntesten Schüler des Gymnasiums war der österreichische Bundespräsident Thomas Klestil (1932-2004), nach dem seit 2006 auch ein zentraler Platz im Stadtteil [[Erdberg]] benannt ist"}]'::jsonb, ''),
  ('leonhardgossn', 'Leonhardgossn', '', '', '', '', 'Leonhardgasse', '[{"kategorie": "allg.", "text": "\"Straße im Bezirksteil [[Erdberg]] des 3. Wiener Gemeindebezirks ([[Landstraße]])\""}, {"kategorie": "", "text": "Ihren Namen verdankt sie dem Hausschild „Zum heiligen Leonhard“, das in dieser Gegend zu finden war"}, {"kategorie": "", "text": "An der Leonhardgasse 4-6 befindet sich eine städtische Wohnhausanlage aus den 1950er Jahren, an die eine Marienkapelle mit einer steinernen Darstellung der „Magna Mater Austriae“ angebaut ist. Diese Skulptur ist eine Nachbildung der berühmten Mariazeller Muttergottes"}, {"kategorie": "", "text": "Besonders markant ist eine in die Kapelle eingemauerte Türkenkugel aus dem Jahr 1683, die an die [[Zweite]] Türkenbelagerung Wiens erinnert. Die Kapelle wurde ursprünglich 1815 errichtet, während des [[Zweiten]] Weltkriegs schwer beschädigt und 1957 restauriert. Nach der Assanierung des Viertels Alterdberg wurde die Kapelle 1958 in ihrer alten Form an den Neubau in der Leonhardgasse versetzt"}, {"kategorie": "", "text": "Eine Gedenktafel in der Leonhardgasse erinnert an die historische Bedeutung des Viertels und enthält eine Darstellung von Alterdberger Häusern sowie das Lied „Da drunt'' in Erdberg is'' a Gasserl...“ von Albert Freiherr von Hacke"}, {"kategorie": "", "text": "Die Leonhardgasse verläuft heute am Rand des historischen Dorfes Nottendorf, einer mittelalterlichen Ansiedlung im heutigen Wiener Stadtteil Erdberg, die erstmals 1389 urkundlich erwähnt wurde. Der Name „Nottendorf“ leitet sich aus dem Niederdeutschen ab und bedeutet „Dorf der Genossen“"}, {"kategorie": "", "text": "Nottendorf hatte eine genossenschaftliche Dorfverfassung und erstreckte sich vom Gebiet der heutigen Erdberger Pfarrkirche über den [[Kardinal-Nagl-Platz]] bis zur [[Leonhardgasse]].Während der [[Ersten]] Türkenbelagerung im Jahr 1529 wurde Nottendorf vollständig zerstört und nie wieder aufgebaut. Die [[Nottendorfer]] Gasse erinnert heute an diese historische Siedlung"}]'::jsonb, ''),
  ('nationalbibliothek', 'Nationalbibliothek', '', '', '', '', 'Nationalbibliothek', '[{"kategorie": "allg.", "text": "\"größte Bibliothek Österreichs und eine der bedeutendsten Bibliotheken der Welt\" (kurz auch \"ÖNB\")"}, {"kategorie": "", "text": "Sie befindet sich in der [[Neuen]] Burg am [[Heldenplatz]], die historischen Sammlungen und die Verwaltung sind vom benachbarten [[Josefsplatz]] zugänglich. Weitere Abteilungen befinden sich in anderen Teilen der [[Hofburg]] und im [[Palais]] Mollard-Clary in der [[Herrengasse]]"}, {"kategorie": "", "text": "Die Wurzeln der Österreichischen Nationalbibliothek reichen bis ins 15. Jahrhundert zurück, als sie noch als Hofbibliothek der Habsburger diente. Kaiser [[Friedrich]] III. gilt als einer ihrer ersten Begründer"}, {"kategorie": "", "text": "Die prächtigste Erweiterung erfuhr die Bibliothek unter [[Karl]] VI., der den berühmten barocken Prunksaal in der Hofburg errichten ließ, der heute eine der Hauptattraktionen der Bibliothek ist"}, {"kategorie": "", "text": "Ihren heutigen Namen erhielt die Bibliothek 1920 nach dem Ende der [[Habsburgermonarchie]]. Zuvor war sie als Kaiserliche Hofbibliothek bekannt"}, {"kategorie": "", "text": "Die Österreichische Nationalbibliothek umfasst etwa 12 Millionen Objekte, darunter Bücher, Handschriften, historische Dokumente, Karten, Musikalien und Grafiken. Ihre Sammlungen umfassen folgende bedeutende Abteilungen: (i) Büchersammlung (mit Millionen von Büchern und Zeitschriften aus unterschiedlichen Epochen, darunter wertvolle Inkunabeln (Frühdrucke) und seltene historische Werke); (ii) Handschriftensammlung (diese Sammlung umfasst etwa 180.000 Manuskripte und Handschriften, darunter mittelalterliche Codices, Papyri und Dokumente aus dem Habsburger Reich);  (iii) Kartensammlung (die ÖNB beherbergt eine der größten Kartensammlungen der Welt mit etwa 400.000 Karten und Atlanten, die die geographische Geschichte abbilden);  (iv) Papyrussammlung (diese umfasst über 180.000 Stücke und gehört zu den weltweit bedeutendsten Sammlungen antiker Papyri);  sowie (v) Porträt- und Bildersammlung (diese Sammlung enthält mehr als 600.000 historische Grafiken, Drucke und Fotografien, die eine visuelle Dokumentation der europäischen Geschichte darstellen)"}, {"kategorie": "", "text": "Der Prunksaal ist das Herzstück der Österreichischen Nationalbibliothek und gilt als einer der schönsten Barocksäle der Welt. Er wurde im 18. Jahrhundert von Johann Bernhard Fischer von Erlach entworfen und von Maria Theresia fertiggestellt. Der Saal enthält etwa 200.000 Bände, darunter zahlreiche wertvolle Werke"}, {"kategorie": "", "text": "Die ÖNB hat eine gesetzliche Pflicht zur Pflichtexemplarsammlung, was bedeutet, dass sie ein Exemplar jedes in Österreich erschienenen Buches erhält und archiviert"}, {"kategorie": "", "text": "Neben dem Prunksaal beherbergt die Österreichische Nationalbibliothek mehrere Museen, darunter: (i) das Papyrusmuseum (dieses Museum zeigt antike Schriften und Dokumente aus der Papyrussammlung);  (ii) das Globenmuseum (hier werden historische Globen aus verschiedenen Epochen ausgestellt);  sowie das\nEsperantomuseum (eine Sammlung, die sich mit der internationalen Sprache Esperanto und anderen Plansprachen befasst)"}, {"kategorie": "", "text": "Mit ihren umfangreichen Beständen, ihrer reichen Geschichte und ihren weltberühmten Sälen wie dem Prunksaal ist die ÖNB nicht nur eine der bedeutendsten Bibliotheken Europas, sondern auch ein Wahrzeichen Wiens."}]'::jsonb, ''),
  ('oenb', 'ÖNB', '', '', '', '', 'ÖNB', '[{"kategorie": "Abkürzung für", "text": "\"Österreichische Nationalbibliothek\" = \"größte Bibliothek Österreichs und eine der bedeutendsten Bibliotheken der Welt\" (kurz auch \"ÖNB\")"}, {"kategorie": "", "text": "Sie befindet sich in der [[Neuen]] Burg am [[Heldenplatz]], die historischen Sammlungen und die Verwaltung sind vom benachbarten [[Josefsplatz]] zugänglich. Weitere Abteilungen befinden sich in anderen Teilen der [[Hofburg]] und im [[Palais]] Mollard-Clary in der [[Herrengasse]]"}, {"kategorie": "", "text": "Die Wurzeln der Österreichischen Nationalbibliothek reichen bis ins 15. Jahrhundert zurück, als sie noch als Hofbibliothek der Habsburger diente. Kaiser [[Friedrich]] III. gilt als einer ihrer ersten Begründer"}, {"kategorie": "", "text": "Die prächtigste Erweiterung erfuhr die Bibliothek unter [[Karl]] VI., der den berühmten barocken Prunksaal in der Hofburg errichten ließ, der heute eine der Hauptattraktionen der Bibliothek ist"}, {"kategorie": "", "text": "Ihren heutigen Namen erhielt die Bibliothek 1920 nach dem Ende der [[Habsburgermonarchie]]. Zuvor war sie als Kaiserliche Hofbibliothek bekannt"}, {"kategorie": "", "text": "Die Österreichische Nationalbibliothek umfasst etwa 12 Millionen Objekte, darunter Bücher, Handschriften, historische Dokumente, Karten, Musikalien und Grafiken. Ihre Sammlungen umfassen folgende bedeutende Abteilungen: (i) Büchersammlung (mit Millionen von Büchern und Zeitschriften aus unterschiedlichen Epochen, darunter wertvolle Inkunabeln (Frühdrucke) und seltene historische Werke); (ii) Handschriftensammlung (diese Sammlung umfasst etwa 180.000 Manuskripte und Handschriften, darunter mittelalterliche Codices, Papyri und Dokumente aus dem Habsburger Reich);  (iii) Kartensammlung (die ÖNB beherbergt eine der größten Kartensammlungen der Welt mit etwa 400.000 Karten und Atlanten, die die geographische Geschichte abbilden);  (iv) Papyrussammlung (diese umfasst über 180.000 Stücke und gehört zu den weltweit bedeutendsten Sammlungen antiker Papyri);  sowie (v) Porträt- und Bildersammlung (diese Sammlung enthält mehr als 600.000 historische Grafiken, Drucke und Fotografien, die eine visuelle Dokumentation der europäischen Geschichte darstellen)"}, {"kategorie": "", "text": "Der Prunksaal ist das Herzstück der Österreichischen Nationalbibliothek und gilt als einer der schönsten Barocksäle der Welt. Er wurde im 18. Jahrhundert von Johann Bernhard Fischer von Erlach entworfen und von Maria Theresia fertiggestellt. Der Saal enthält etwa 200.000 Bände, darunter zahlreiche wertvolle Werke"}, {"kategorie": "", "text": "Die ÖNB hat eine gesetzliche Pflicht zur Pflichtexemplarsammlung, was bedeutet, dass sie ein Exemplar jedes in Österreich erschienenen Buches erhält und archiviert"}, {"kategorie": "", "text": "Neben dem Prunksaal beherbergt die Österreichische Nationalbibliothek mehrere Museen, darunter: (i) das Papyrusmuseum (dieses Museum zeigt antike Schriften und Dokumente aus der Papyrussammlung);  (ii) das Globenmuseum (hier werden historische Globen aus verschiedenen Epochen ausgestellt);  sowie das\nEsperantomuseum (eine Sammlung, die sich mit der internationalen Sprache Esperanto und anderen Plansprachen befasst)"}, {"kategorie": "", "text": "Mit ihren umfangreichen Beständen, ihrer reichen Geschichte und ihren weltberühmten Sälen wie dem Prunksaal ist die ÖNB nicht nur eine der bedeutendsten Bibliotheken Europas, sondern auch ein Wahrzeichen Wiens."}]'::jsonb, ''),
  ('salmgossn', 'Salmgossn', '', '', '', '', 'Salmgasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße in einem gehobenen Viertel des 3. Wiener Gemeindebezirks ([[Landstraße]]), benannt nach der Adelsfamilie Salm-Reifferscheidt bzw. nach deren [[Palais]] Salm\""}, {"kategorie": "", "text": "Das Adelsgeschlecht der Grafen Salm-Reifferscheidt spielte über Jahrhunderte hinweg eine bedeutende Rolle in der [[Habsburgermonarchie]], hatte enge Verbindungen zum kaiserlichen Hof und erlangte durch ihre politischen und militärischen Verdienste hohen gesellschaftlichen Status"}, {"kategorie": "", "text": "Die Familie ließ in der Salmgasse das [[Palais]] Salm errichten, das eines der wichtigsten Gebäude in dieser Straße ist"}, {"kategorie": "", "text": "Heute ist die Salmgasse eine ruhige Wohnstraße, die im Vergleich zu den belebteren Teilen des 3. Bezirks weniger frequentiert wird. Sie bietet eine historische Atmosphäre durch die gut erhaltenen Altbauten und Palais, sowie auch durch seine Nähe zum [[Schloss]] Belvedere."}]'::jsonb, ''),
  ('historismus', 'Historismus', '', '', '', '', 'Historismus', '[{"kategorie": "allg.", "text": "\"architektonische und kunstgeschichtliche Stilrichtung, die im 19. Jahrhundert in Europa aufkam\""}, {"kategorie": "", "text": "Er zeichnet sich dadurch aus, dass er auf frühere Epochen der Kunst- und Architekturgeschichte zurückgreift und diese Stilelemente in einem neuen Kontext vereint"}, {"kategorie": "", "text": "Der Historismus bediente sich einer Vielzahl von historischen Stilen wie Romanik, Gotik, Renaissance, Barock und [[Klassizismus]] und kombinierte sie teilweise zu neuen, eklektischen Kompositionen"}, {"kategorie": "", "text": "Eines der bekanntesten Beispiele für den Historismus ist die [[Wiener]] Ringstraße, die im späten 19. Jahrhundert angelegt wurde"}, {"kategorie": "", "text": "Die Gebäude entlang der Ringstraße, darunter das [[Parlament]] (im griechischen Klassizismus), das [[Rathaus]] (im neugotischen Stil) und die [[Universität]] Wien (im Neorenaissance-Stil), illustrieren den stilistischen Reichtum"}, {"kategorie": "", "text": "Der Eklektizismus des Historismus reflektierte den Wunsch nach repräsentativer Architektur, die sich bewusst auf die Vergangenheit bezieht."}]'::jsonb, ''),
  ('globnmuseum', 'Globnmuseum', '', '', '', '', 'Globenmuseum', '[{"kategorie": "allg.", "text": "\"einzigartiges Museum, das sich ausschließlich der Ausstellung und Erforschung von historischen Globen widmet\""}, {"kategorie": "", "text": "Es ist Teil der [[Österreichischen]] Nationalbibliothek und befindet sich im [[Palais]] Mollard-Clary in der [[Herrengasse]] 9 im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Das Globenmuseum ist weltweit das einzige seiner Art und zeigt eine umfassende Sammlung von Globen und Karten, die geografische, astronomische und politische Weltansichten aus verschiedenen Epochen widerspiegeln"}, {"kategorie": "", "text": "Das Globenmuseum wurde 1956 gegründet und basiert auf der Sammlung der Österreichischen Nationalbibliothek, die bereits im 19. Jahrhundert historische Globen erwarb"}, {"kategorie": "", "text": "Das Globenmuseum beherbergt etwa 250 Objekte, darunter Erdgloben, Himmelsgloben, Mondgloben, Planetengloben und Globen mit speziellem thematischen Fokus. Diese Globen stammen aus verschiedenen Epochen und zeigen, wie sich das Wissen über die Welt und das Universum im Laufe der Jahrhunderte verändert hat"}, {"kategorie": "", "text": "Mit seiner außergewöhnlichen Sammlung, die die Geschichte des wissenschaftlichen Weltbildes über Jahrhunderte hinweg illustriert, gehört es zu den bedeutendsten kulturellen Institutionen im Bereich der Kartographie und Wissenschaftsgeschichte. Das Globenmuseum bietet eine faszinierende Reise durch die Darstellung der Erde, der Sterne und des Universums von der frühen Neuzeit bis heute."}]'::jsonb, ''),
  ('esperantomuseum', 'Esperantomuseum', '', '', '', '', 'Esperantomuseum', '[{"kategorie": "allg.", "text": "\" weltweit einzigartiges Museum, das sich der internationalen Plansprache Esperanto und anderen Plansprachen widmet\""}, {"kategorie": "", "text": "Es ist Teil der [[Österreichischen]] Nationalbibliothek und befindet sich im [[Palais]] Mollard-Clary in der [[Herrengasse]] 9 im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Das Museum dokumentiert die Geschichte, Entwicklung und Nutzung von Esperanto sowie anderer Plansprachen und ist sowohl ein Zentrum der Forschung als auch der Bildung"}, {"kategorie": "", "text": "Das Esperantomuseum wurde im Jahr 1927 vom Esperantisten Hugo Steiner gegründet. Von Anfang an war es dem Ziel gewidmet, die Idee einer internationalen Sprache zu fördern und die vielfältigen Bestrebungen in diesem Bereich zu dokumentieren"}, {"kategorie": "", "text": "1928 wurde es offiziell in die Österreichische Nationalbibliothek integriert. Das Museum hat seither kontinuierlich seine Sammlung erweitert und gilt heute als eine der weltweit bedeutendsten Institutionen zur Erforschung und Dokumentation von Esperanto und Plansprachen"}, {"kategorie": "", "text": "Die Sammlung umfasst (i) Werke in und über Esperanto (darunter Übersetzungen von klassischen literarischen Werken sowie originale Esperanto-Texte), (ii) Dokumente zur Sprachgeschichte (historische Dokumente zur Entstehung und Entwicklung von Esperanto, das von Ludwig Zamenhof im Jahr 1887 geschaffen wurde, um als neutrale internationale Sprache die Verständigung zwischen Menschen verschiedener Nationen zu erleichtern), sowie (iii) Sammlung zu anderen Plansprachen (neben Esperanto widmet sich das Museum auch anderen Plansprachen wie Ido, Volapük, Interlingua und weiteren, die als Alternative zu Esperanto entwickelt wurden) und (iv) Filme, Tonaufnahmen und digitale Medien, die die Anwendung und Verbreitung von Esperanto in der modernen Welt dokumentieren"}, {"kategorie": "", "text": "Das Esperantomuseum dient nicht nur als Ausstellungsort, sondern auch als Forschungszentrum für Plansprachen. Es arbeitet eng mit internationalen Esperanto-Organisationen und Sprachforschern zusammen, um die Verbreitung und Entwicklung von Esperanto und anderen Plansprachen zu dokumentieren."}]'::jsonb, ''),
  ('mollardgossn', 'Mollardgossn', '', '', '', '', 'Mollardgasse', '[{"kategorie": "allg.", "text": "\"belebte Wohn- und Geschäftsstraße im 6. Wiener Gemeindebezirk ([[Mariahilf]])\""}, {"kategorie": "", "text": "Sie ist benannt nach dem Geschlecht der Grafen Mollard, dessen Angehörige 1629-1759 Besitzer der Herrschaft [[Gumpendorf]] waren"}, {"kategorie": "", "text": "Die Familie war eng mit dem Wiener Adel und dem Habsburgerhof verbunden, insbesondere Maria Anna von Mollard, die Erzieherin von Kaiserin [[Maria]] Theresia, spielte eine wichtige Rolle am Hof"}, {"kategorie": "", "text": "Die Bebauung entlang der Mollardgasse besteht hauptsächlich aus historischen Zinshäusern aus dem späten 19. und frühen 20. Jahrhundert. Die Architektur ist typisch für die Wiener [[Gründerzeit]] mit ihren prächtigen Fassaden und ornamentalen Verzierungen."}]'::jsonb, ''),
  ('minoritnkiachn', 'Minoritnkiachn', '', '', '', '', 'Minoritenkirche', '[{"kategorie": "allg.", "text": "\"eine der ältesten und bedeutendsten Kirchen Wiens. Sie befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) am [[Minoritenplatz]] in unmittelbarer Nähe zur [[Hofburg]] und ist ein herausragendes Beispiel der gotischen Architektur in Wien\""}, {"kategorie": "", "text": "Die Kirche wurde im 13. Jahrhundert von den Minoriten, einem Zweig des Franziskanerordens, gegründet. Ihr vollständiger Name lautet \"Kirche der Minderbrüder\" (Ecclesia Fratrum Minorum), doch sie wird allgemein als Minoritenkirche bezeichnet"}, {"kategorie": "", "text": "Die Fratres minores (Minoriten) wurden 1224 von Leopold VI. nach Wien berufen und errichteten sich nahe der neuen Stadtmauer einen kleinen (erstmals 1234 erwähnt) Konvent und eine 1251 durch Bischof Berthold von Passau geweihte Kapelle (\"Zum heiligen Kreuz\")"}, {"kategorie": "", "text": "Nach dem Stadtbrand von 1275 wurde von König Ottokar Přemysl der Grundstein für die neue Kirche des Minoritenklosters gelegt. Sie war eine der ersten gotischen Kirchen im ostösterreichischen Raum und bestand wahrscheinlich aus einem zweischiffigen Langhaus mit angeschlossenem Langchor. Nach Ottokars Tod in der Schlacht auf dem Marchfeld wurde er hier dreißig Wochen aufgebahrt"}, {"kategorie": "", "text": "Ursprünglich war die Kirche als eine basilikale Anlage konzipiert, deren schlichte Eleganz und vertikale Linien die für die Gotik charakteristische Hinwendung zum Himmel widerspiegeln sollten"}, {"kategorie": "", "text": "Insgesamt repräsentiert die nahe an der [[Wiener]] Hofburg gelegene Kirche aber eher einen höfisch beeinflussten Stil als die typische Bettelordensarchitektur, was auch dadurch zum Ausdruck kommt, dass sie einen Turm besitzt (welcher im Zuge der à1. Türkenbelagerung mehrmals abgeschossen wurde, da man von der Turmspitze einen sehr guiten Ausblick hatte)"}, {"kategorie": "", "text": "Im Inneren der Minoritenkirche befindet sich eine Mosaikkopie von Leonardo da Vincis \"Das letzte Abendmahl\", die im Auftrag von Napoleon Bonaparte angefertigt wurde. Das imposante Kunstwerk nimmt eine ganze Wand ein und ist eines der eindrucksvollsten Merkmale der Kirche."}]'::jsonb, ''),
  ('boihausplotz', 'Boihausplotz', '', '', '', '', 'Ballhausplatz', '[{"kategorie": "allg.", "text": "\"historisch und politisch bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Er liegt unmittelbar neben der [[Hofburg]] und ist seit Jahrhunderten ein zentrales Zentrum der politischen Macht in Österreich"}, {"kategorie": "", "text": "Am Ballhausplatz befinden sich zwei der wichtigsten politischen Gebäude des Landes: das Bundeskanzleramt und die Präsidentschaftskanzlei"}, {"kategorie": "", "text": "Der Ballhausplatz erhielt seinen Namen von einem Ballhaus, das im 17. Jahrhundert auf dem Gelände stand und für das damals beliebte Ballspiel Jeu de Paume genutzt wurde, einem Vorläufer des heutigen Tennis"}, {"kategorie": "", "text": "Seit dem 18. Jahrhundert entwickelte sich der Platz zu einem politischen Zentrum, als das kaiserliche Hofkanzleigebäude errichtet wurde, das später zum Sitz des österreichischen Kanzlers und anderer Regierungsbehörden wurde"}, {"kategorie": "", "text": "Im Leopoldinischen Trakt der Hofburg, der an den Ballhausplatz angrenzt, befindet sich die Präsidentschaftskanzlei. Hier arbeitet der österreichische Bundespräsident und nimmt seine repräsentativen und politischen Aufgaben wahr"}, {"kategorie": "", "text": "Der Ballhausplatz ist nach wie vor ein wichtiger politischer Knotenpunkt in Wien. Er ist der Sitz der Regierung und oft Schauplatz für politische Veranstaltungen und Demonstrationen."}]'::jsonb, ''),
  ('gonzagabastei', 'Gonzagabastei', '', '', '', '', 'Gonzagabastei', '[{"kategorie": "", "text": "Sie wurde nach der adeligen italienischen Familie Gonzaga benannt, die im 16. und 17. Jahrhundert enge Verbindungen zum österreichischen Kaiserhaus und zum Wiener Hof hatte"}, {"kategorie": "", "text": "Die Gonzagabastei war Teil der Wiener Stadtbefestigungen, die vor allem im 16. Jahrhundert verstärkt wurden, um die Stadt gegen Angriffe zu verteidigen, insbesondere während der [[Türkenkriege]]. Diese Stadtmauern waren entscheidend für die Verteidigung Wiens, etwa bei der [[Ersten]] Türkenbelagerung 1529 und der [[Zweiten]] Türkenbelagerung 1683"}, {"kategorie": "", "text": "Im Jahr 1857 ließ Kaiser [[Franz]] Joseph I. die Wiener [[Stadtmauern]] und viele der alten [[Basteien]], darunter die Gonzagabastei, abtragen, um Platz für die [[Ringstraße]] und ihre prächtigen neuen Gebäude zu schaffen."}]'::jsonb, ''),
  ('bastei', 'Bastei', '', '', '', '', 'Bastei', '[{"kategorie": "wörtlich", "text": "\"vorspringendes Bollwerk an Festungsmauern\" (vom italienischen \"bastia\"=\"Bollwerk\")"}, {"kategorie": "hist.", "text": "Wehrmauer, Festungsmauer, Stadtmauer"}]'::jsonb, ''),
  ('soizgrias', 'Soizgrias', '', '', '', '', 'Salzgries', '[{"kategorie": "allg.", "text": "\"historische Straße in einem der ältesten Stadtteile Wiens im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Die Straße beginnt am [[Morzinplatz]] (in der Nähe des [[Donaukanals]]) und erstreckt sich bis zur [[Werdertorgasse]]"}, {"kategorie": "", "text": "Schon zur Zeit der Römer bestand hier eine Uferstraße zwischen Lagermauer und schiffbarem Strom, welche jedoch außerhalb der Stadtmauer lag"}, {"kategorie": "", "text": "Die Gegend, ursprünglich \"An dem Gries\" (sandiges Ufer) genannt, heißt seit 1322 Salzgries. Da hier (\"am Gestade\") der südlichste Donauarm floss, konnten die auf der Donau ankommenden Salzschiffe unmittelbar anlegen"}, {"kategorie": "", "text": "Der Name weist auf dessen frühere Verwendung als Handels- und Lagerplatz für Salz ab, das im Mittelalter ein bedeutender Handelsartikel war"}, {"kategorie": "", "text": "Der Salzgries gehört zu den ältesten Straßen der Wiener Innenstadt und erinnert durch seinen Namen an die wichtige historische Rolle des Salzhandels für die Entwicklung Wiens."}]'::jsonb, ''),
  ('moasinplotz', 'Moasinplotz', '', '', '', '', 'Morzinplatz', '[{"kategorie": "allg.", "text": "historisch bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), direkt am [[Donaukanal]] gelegen, unweit des [[Schwedenplatzes]]"}, {"kategorie": "", "text": "Der Morzinplatz trägt seinen Namen seit dem 19. Jahrhundert und ist nach der böhmischen Adelsfamilie Morzin benannt (konkret nach Vinzenz Graf Morzin, der als letzter seines Geschlechts der Stadt Wien eine Million Gulden für Arme, Waisen und körperbehinderte Kinder vermacht hatte)"}, {"kategorie": "", "text": "Am Morzinplatz mündete bis ins 16. Jahrhundert der stadtnächste (nicht mehr existente) Donauarm ([[Salzgries]]) in den Donaukanal. Der Uferstreifen vor der Ringmauer ([[Salzgries]]) diente der Stadt Wien bis 1561 als Schiffsanlegeplatz"}, {"kategorie": "", "text": "Während des Zweiten Weltkriegs und der Zeit der nationalsozialistischen Herrschaft spielte der Morzinplatz eine tragische Rolle. Dort befand sich das Hotel Metropol, das von 1938 bis 1945 als Sitz der Gestapo-Leitstelle Wien diente"}, {"kategorie": "", "text": "Das Gebäude wurde 1945 bei Kriegsende zerstört. Heute erinnert ein Mahnmal am Morzinplatz an die Opfer der Gestapo und die Verbrechen, die von hier aus während der nationalsozialistischen Herrschaft verübt wurden. Das von Leopold Grausam geschaffene Mahnmal für die Opfer des Faschismus  wurde 1951 errichtet und ist ein zentraler Ort des Gedenkens in Wien"}, {"kategorie": "", "text": "Der Morzinplatz ist heute eine zentrale Verkehrs- und Geschäftszone. Zahlreiche Bürogebäude, Hotels und Restaurants säumen den Platz und machen ihn zu einem lebendigen Teil der Wiener Innenstadt."}]'::jsonb, ''),
  ('rudoifsplotz', 'Rudoifsplotz', '', '', '', '', 'Rudolfsplatz', '[{"kategorie": "allg.", "text": "historischer Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und liegt im nördlichen Teil des Zentrums von Wien, in der Nähe des [[Donaukanals]], westlich des [[Schwedenplatzes]] und unweit des [[Salzgries]] sowie der [[Werdertorgasse]]."}, {"kategorie": "", "text": "Der Platz wurde nach [[Kronprinz]] Rudolf, dem Sohn von Kaiser [[Franz]] Joseph I. und Kaiserin Elisabeth ([[Sisi]]), benannt"}, {"kategorie": "", "text": "Der Rudolfsplatz wurde im 19. Jahrhundert benannt, als Wien in der [[Gründerzeit]] stark expandierte. Er erinnert an Kronprinz Rudolf, der als Thronfolger der Habsburger viele Hoffnungen in sich trug, jedoch tragischerweise 1889 im Alter von 30 Jahren in Mayerling mit seiner Geliebten Mary Vetsera Selbstmord beging"}, {"kategorie": "", "text": "Der Platz wird von einer Parkanlage dominiert, die als Grünfläche im dicht bebauten Stadtzentrum dient. Die parkähnliche Gestaltung verleiht dem Platz eine ruhige, entspannte Atmosphäre"}, {"kategorie": "", "text": "Eines der bekanntesten Gebäude am Rudolfsplatz ist das [[Palais]] Lieben-Auspitz, ein prächtiges Palais, das im 19. Jahrhundert errichtet wurde und heute als Büro- und Geschäftsgebäude dient."}]'::jsonb, ''),
  ('oppoizagossn', 'Oppoizagossn', '', '', '', '', 'Oppolzergasse', '[{"kategorie": "allg.", "text": "\"kurze, zentrale Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die sich zwischen dem [[Universitätsring]] und der [[Freyung]]\""}, {"kategorie": "", "text": "Sie wurde nach dem österreichischen Arzt und Mediziner Johann Ritter von Oppolzer benannt, einem renommierten Internisten und Professor an der Universität Wien, der im 19. Jahrhundert einen bedeutenden Beitrag zur Entwicklung der Medizin leistete"}, {"kategorie": "", "text": "Johann Ritter von Oppolzer (1808–1871) war ein herausragender Mediziner des 19. Jahrhunderts. Er wirkte als Internist, Diagnostiker und Kliniker und war einer der bedeutendsten Ärzte seiner Zeit"}, {"kategorie": "", "text": "Er war Professor an der Medizinischen Fakultät der Universität Wien, die damals als eines der führenden medizinischen Zentren Europas galt. Oppolzer leistete einen wesentlichen Beitrag zur Entwicklung der klinischen Medizin und prägte viele Generationen von Ärzten"}, {"kategorie": "", "text": "In der Oppolzergasse befand sich der Eingang zum einst legendären [[Literarischen]] Salon von Berta Zuckerkandl-Szeps im [[Palais]] Lieben-Auspitz."}]'::jsonb, ''),
  ('robnschdeig', 'Robnschdeig', '', '', '', '', 'Rabensteig', '[{"kategorie": "allg.", "text": "\"kurze, historische Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die von der [[Rotenturmstraße]] bis zum [[Salzgries]] verläuft und in einem der ältesten Stadtteile Wiens liegt\""}, {"kategorie": "", "text": "Die Gasse hieß im Mittelalter (belegt ab 1346) und in der frühen Neuzeit \"Auf der Mörung\", ab dem 18. Jahrhundert dann \"Rabengasse\" (nach dem Hausschild \"Zu den drei [schwarzen] Raben\", an der Stelle des heutigen Hauses an der Adresse \"Rabensteig 1\""}, {"kategorie": "", "text": "Im Mittelalter und in der frühen Neuzeit war der Rabensteig Teil eines dichten Netzes von Gassen in der Wiener Innenstadt, das von Kaufleuten, Handwerkern und Schiffern genutzt wurde. Der Donaukanal war ein wichtiger Transportweg, und das Viertel um den Rabensteig war ein Zentrum für Handel und Warenumschlag"}, {"kategorie": "", "text": "In den letzten Jahren haben sich entlang des Rabensteigs und in den benachbarten Straßen zahlreiche Restaurants, Bars und Geschäfte etabliert, die das Viertel zu einem lebendigen Teil der Wiener Innenstadt machen"}]'::jsonb, ''),
  ('seitnschdettngossn', 'Seitnschdettngossn', '', '', '', '', 'Seitenstettengasse', '[{"kategorie": "allg.", "text": "\"kleine, aber historisch bedeutende Straße im 1. Wiener Bezirk ([[Innere]] Stadt), die sich in der Nähe des [[Judenplatzes]] befindet\""}, {"kategorie": "", "text": "Sie ist eng mit der jüdischen Geschichte der Stadt verbunden und liegt heute mitten im beliebten Ausgehviertel [[Bermuda-Dreieck]]"}, {"kategorie": "", "text": "Ihren Namen hat sie vom Stift Seitenstetten, das am 25. April 1825 mehrere Häuser in dieser Gasse erwarb"}, {"kategorie": "", "text": "Die Seitenstettengasse ist besonders bekannt für die dort gelegene [[Stadttempel-Synagoge]], auch als Seitenstettengasse Synagoge bezeichnet. Diese Synagoge wurde 1825–1826 im Biedermeier-Stil erbaut und ist das wichtigste jüdische Gotteshaus in Wien"}, {"kategorie": "", "text": "Sie ist die einzige Synagoge, die die Novemberpogrome von 1938 (die sogenannte Reichskristallnacht) überstanden hat, da sie in einem dicht bebauten Block liegt und die Gefahr bestand, umliegende Gebäude bei einer Zerstörung zu gefährden"}, {"kategorie": "", "text": "Heute dient sie als Zentrum der Israelitischen Kultusgemeinde Wien (IKG) und spielt eine wichtige Rolle im religiösen und kulturellen Leben der jüdischen Gemeinde in Wien"}, {"kategorie": "", "text": "Neben ihrer religiösen und historischen Bedeutung hat die Seitenstettengasse heute auch einen Ruf als Ausgehmeile. Die Straße ist Teil des [[Bermuda-Dreiecks]], einem beliebten Viertel für Nachtschwärmer, das eine große Auswahl an Bars, Kneipen und Restaurants bietet. Besonders in den Abendstunden ist die Gegend um die Seitenstettengasse belebt, da sie ein zentraler Treffpunkt für das Wiener Nachtleben ist."}]'::jsonb, ''),
  ('justizpalastbraund', 'Justizpalastbraund', '', '', '', '', 'Justizpalastbrand', '[{"kategorie": "allg.", "text": "\"bedeutendes Ereignis der österreichischen Zwischenkriegszeit, welches sich am 15. Juli 1927 ereignete\""}, {"kategorie": "hist.", "text": "Der Justizpalastbrand wurde durch die Freisprechung von Angeklagten in einem Fall von politisch motivierter Gewalt ausgelöst. Im Jahr 1927 war es in Schattendorf, einem Dorf im Burgenland, zu einem Zwischenfall gekommen, bei dem Mitglieder der paramilitärischen rechtsgerichteten Frontkämpfervereinigung ([[Heimwehr]]) das Feuer auf eine sozialdemokratische Demonstration eröffneten. Dabei wurden ein Kind und ein älterer Mann erschossen. Im anschließenden Gerichtsprozess, der im Juli 1927 in Wien stattfand, wurden die Angeklagten freigesprochen, was bei vielen Menschen Empörung und Wut hervorrief, vor allem in den Reihen der Sozialdemokratischen Arbeiterpartei (SDAP)"}, {"kategorie": "", "text": "Am 15. Juli 1927 kam es nach Bekanntgabe des Urteils zu massiven Protesten in Wien, an denen Zehntausende Menschen teilnahmen. Der Protestmarsch führte zu gewalttätigen Ausschreitungen, die sich auf den Justizpalast konzentrierten, der als Symbol für die als ungerecht empfundene Justiz angesehen wurde. Demonstranten drangen in das Gebäude ein und setzten es in Brand. Die Flammen breiteten sich schnell aus, und Teile des Justizpalastes wurden schwer beschädigt"}, {"kategorie": "", "text": "Die Regierung unter Bundeskanzler Ignaz Seipel, die von der konservativen Christlichsozialen Partei geführt wurde, reagierte mit der Ausrufung des Ausnahmezustands. Die Polizei und die Bundesheer-Einheiten wurden eingesetzt, um die Unruhen niederzuschlagen. In den folgenden Zusammenstößen schoss die Polizei in die Menge, was zu einem Massaker führte. Insgesamt wurden 89 Demonstranten und 5 Polizisten getötet, und mehr als 1000 Menschen wurden verletzt"}, {"kategorie": "", "text": "Der Justizpalastbrand und die nachfolgende blutige Niederschlagung der Proteste vertieften die ohnehin tiefen politischen Gräben zwischen den sozialistischen und konservativen Kräften in Österreich. Das Ereignis trug zur weiteren Radikalisierung der politischen Lager bei und war ein Meilenstein auf dem Weg zum Austrofaschismus und zur Diktatur in den 1930er Jahren."}]'::jsonb, ''),
  ('reichskristoinocht', 'Reichskristoinocht', '', '', '', '', 'Reichskristallnacht', '[{"kategorie": "allg.", "text": "die Nacht vom 9. auf den 10. November 1938, in der es zu einer Serie gewaltsamer Übergriffe gegen jüdische Menschen, Geschäfte, Wohnungen, Synagogen und andere Einrichtungen im gesamten Deutschen Reich, darunter auch in Wien, kam (auch als [[Novemberpogrome]] 1938 bekannt)"}, {"kategorie": "", "text": "Die Pogrome wurden von den Nationalsozialisten organisiert und markierten eine dramatische Eskalation der Verfolgung der jüdischen Bevölkerung, die schließlich in den Holocaust mündete"}, {"kategorie": "", "text": "Die Reichskristallnacht fand im Kontext einer systematischen antisemitischen Politik des NS-Regimes statt, die bereits seit der Machtübernahme Hitlers im Jahr 1933 kontinuierlich aufgebaut wurde. Die unmittelbare Ursache der Novemberpogrome war die Ermordung des deutschen Diplomaten Ernst vom Rath am 7. November 1938 durch den 17-jährigen polnischen Juden Herschel Grynszpan in Paris. Das NS-Regime nutzte diesen Vorfall als Vorwand, um gegen die gesamte jüdische Bevölkerung im Deutschen Reich vorzugehen"}, {"kategorie": "", "text": "Propagandaminister Joseph Goebbels rief in einer Rede am Abend des 9. November 1938 zur Rache auf, was in der Folge zu den reichsweiten Ausschreitungen führte"}, {"kategorie": "", "text": "In Wien, das seit dem Anschluss Österreichs an das [[Deutsche]] Reich im März 1938 Teil des Dritten Reiches war, nahmen die Pogrome eine besonders brutale und verheerende Form an. Bereits am Abend des 9. November begannen nationalsozialistische Truppen und zivile Anhänger des NS-Regimes, jüdische Geschäfte, Synagogen und Wohnungen zu plündern und zu zerstören"}, {"kategorie": "", "text": "In Wien gibt es mehrere Gedenkstätten, die an die Opfer dieser schrecklichen Ereignisse erinnern, darunter das [[Holocaust-Mahnmal]] am [[Judenplatz]] und die Shoah-Namensmauern-Gedenkstätte im [[Ostarrichi-Park]]."}]'::jsonb, ''),
  ('novembapogrome', 'Novembapogrome', '', '', '', '', 'Novemberpogrome', '[{"kategorie": "allg.", "text": "\"Novemberpogrome von 1938, auch \"Reichskristallnacht\" genannt (die Nacht vom 9. auf den 10. November in der es zu einer Serie gewaltsamer Übergriffe gegen jüdische Menschen, Geschäfte, Wohnungen, Synagogen und andere Einrichtungen im gesamten Deutschen Reich, darunter auch in Wien, kam\""}, {"kategorie": "", "text": "Die Pogrome wurden von den Nationalsozialisten organisiert und markierten eine dramatische Eskalation der Verfolgung der jüdischen Bevölkerung, die schließlich in den Holocaust mündete"}, {"kategorie": "", "text": "Die Novemberpogrome fanden im Kontext einer systematischen antisemitischen Politik des NS-Regimes statt, die bereits seit der Machtübernahme Hitlers im Jahr 1933 kontinuierlich aufgebaut wurde. Die unmittelbare Ursache der Novemberpogrome war die Ermordung des deutschen Diplomaten Ernst vom Rath am 7. November 1938 durch den 17-jährigen polnischen Juden Herschel Grynszpan in Paris. Das NS-Regime nutzte diesen Vorfall als Vorwand, um gegen die gesamte jüdische Bevölkerung im Deutschen Reich vorzugehen"}, {"kategorie": "", "text": "Propagandaminister Joseph Goebbels rief in einer Rede am Abend des 9. November 1938 zur Rache auf, was in der Folge zu den reichsweiten Ausschreitungen führte"}, {"kategorie": "", "text": "In Wien, das seit dem Anschluss Österreichs an das [[Deutsche]] Reich im März 1938 Teil des Dritten Reiches war, nahmen die Pogrome eine besonders brutale und verheerende Form an. Bereits am Abend des 9. November begannen nationalsozialistische Truppen und zivile Anhänger des NS-Regimes, jüdische Geschäfte, Synagogen und Wohnungen zu plündern und zu zerstören"}, {"kategorie": "", "text": "In Wien gibt es mehrere Gedenkstätten, die an die Opfer dieser schrecklichen Ereignisse erinnern, darunter das Holocaust-Mahnmal am [[Judenplatz]] und die Shoah-Namensmauern-Gedenkstätte im [[Ostarrichi-Park]]."}]'::jsonb, ''),
  ('ruprechtsplotz', 'Ruprechtsplotz', '', '', '', '', 'Ruprechtsplatz', '[{"kategorie": "allg.", "text": "\"historischer Platz im 1. Wiener Bezirk ([[Innere]] Stadt), der zu den ältesten Plätzen Wiens zählt\""}, {"kategorie": "", "text": "Der Platz liegt in der Nähe des [[Donaukanals]] und ist besonders bekannt für die dort befindliche [[Ruprechtskirche]], die als die älteste Kirche Wiens gilt"}, {"kategorie": "", "text": "Der Ruprechtsplatz und seine Umgebung sind Teil des mittelalterlichen Stadtkerns Wiens und bieten einen einzigartigen Einblick in die frühe Geschichte der Stadt"}, {"kategorie": "", "text": "Der Ruprechtsplatz selbst ist relativ klein, umgeben von historischen Gebäuden, die typisch für die mittelalterliche Architektur Wiens sind. Die engen, verwinkelten Gassen rund um den Platz, wie der [[Rabensteig]] und der [[Salzgries]], versetzen Besucher zurück in eine Zeit, als Wien noch eine aufstrebende Handelsstadt war"}, {"kategorie": "", "text": "Heute ist der Ruprechtsplatz nicht nur aufgrund seiner historischen Bedeutung bekannt, sondern auch für sein Nachtleben. In den letzten Jahrzehnten hat sich der Platz und seine Umgebung zu einem beliebten Treffpunkt für Nachtschwärmer entwickelt, vor allem wegen der Nähe zum [[Bermuda-Dreieck]], einem bekannten Wiener Ausgehviertel. Zahlreiche Bars und Clubs befinden sich in der unmittelbaren Umgebung des Platzes, was ihn besonders in den Abendstunden belebt."}]'::jsonb, ''),
  ('ruprechtskiachn', 'Ruprechtskiachn', '', '', '', '', 'Ruprechtskirche', '[{"kategorie": "allg.", "text": "\"eine der ältesten, wenn nicht die älteste Kirche Wiens, die um 740 begründet wurde\""}, {"kategorie": "", "text": "Sie befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), am [[Ruprechtsplatz]] in der Nähe des [[Donaukanals]] und ist dem heiligen Rupert von Salzburg geweiht, dem Schutzpatron der Salzschiffer"}, {"kategorie": "", "text": "Die Ruprechtskirche wurde vermutlich im 11. oder 12. Jahrhundert erbaut. Aufgrund ihrer langen Geschichte und der gut erhaltenen mittelalterlichen Bausubstanz ist die sie ein bedeutendes Zeugnis der Stadtgeschichte Wiens"}, {"kategorie": "", "text": "Die Ruprechtskirche steht auf einem Areal, das früher zur römischen Siedlung [[Vindobona]] gehörte, und war möglicherweise Teil des frühen Stadtkerns Wiens. Ursprünglich befand sie sich nahe dem alten Handelsweg entlang des Donaukanals, was ihre Bedeutung für die Salzschiffer erklärt, die über den Fluss Handel trieben"}, {"kategorie": "", "text": "Die Ruprechtskirche ist ein romanisches Bauwerk mit späteren gotischen und barocken Umbauten. Sie zeichnet sich durch ihre schlichte, aber markante Erscheinung aus"}, {"kategorie": "", "text": "Der quadratische Glockenturm stammt aus dem Mittelalter und dominiert das Bauwerk"}, {"kategorie": "", "text": "Der Innenraum der Kirche ist schlicht gehalten, mit Fresken und Wandmalereien aus verschiedenen Epochen. Besonders bemerkenswert sind die mittelalterlichen Glasfenster, die als die ältesten Glasmalereien Wiens gelten und einen Einblick in die Kunst der Romanik geben"}, {"kategorie": "", "text": "Der barocke Hochaltar der Kirche stammt aus späteren Epochen und steht im Kontrast zur Romanik des übrigen Bauwerks"}, {"kategorie": "", "text": "Heute ist die Ruprechtskirche ein denkmalgeschütztes Gebäude, das für Gottesdienste und vor allem auch für besondere Anlässe und Feiern genutzt wird. Sie ist auch ein beliebter Veranstaltungsort für Kultur- und Musikveranstaltungen. In ihrer Nähe befinden sich viele Bars und Lokale des beliebten Wiener Nachtlebens im [[Bermuda-Dreieck]], was die Kirche zu einem ruhigen Kontrastpunkt inmitten einer belebten Umgebung macht."}]'::jsonb, ''),
  ('vindobona', 'Vindobona', '', '', '', '', 'Vindobona', '[{"kategorie": "hist.", "text": "\"Name eines römischen Militärlagers und einer zugehörigen Siedlung, die sich einst auf dem Gebiet des heutigen Wien befanden\""}, {"kategorie": "", "text": "Das Lager war Teil der nördlichen Grenzverteidigung des Römischen Reiches entlang der Donau und spielte eine wichtige Rolle in der Provinz Pannonia"}, {"kategorie": "", "text": "Vindobona war eine von mehreren bedeutenden römischen Städten und Militärstützpunkten entlang des Limes, der römischen Grenze, die das Reich vor den germanischen Stämmen im Norden schützen sollte"}, {"kategorie": "", "text": "Die Geschichte Vindobonas geht auf die 1. Hälfte des 1. Jahrhunderts n. Chr. zurück, als das römische Imperium seine Grenzen nach Norden ausdehnte und militärische Befestigungen entlang der Donau errichtete. Das Militärlager Vindobona wurde etwa um das Jahr 97 n. Chr. gegründet, unter Kaiser Trajan, und diente als Stützpunkt für römische Legionen"}, {"kategorie": "", "text": "Die bedeutendste Truppe, die in Vindobona stationiert war, war die Legio X Gemina, die hier bis ins 5. Jahrhundert stationiert blieb. Diese Legion war maßgeblich für die Sicherung der römischen Grenze verantwortlich"}, {"kategorie": "", "text": "Vindobona befand sich im heutigen Zentrum von Wien, in etwa zwischen dem [[Schottenring]] und dem [[Stephansdoms]]. Die Überreste des Lagers liegen unter der modernen Stadt und wurden bei archäologischen Ausgrabungen entdeckt"}, {"kategorie": "", "text": "Das römische Lager hatte eine rechteckige Form und war von einer Mauer und Gräben umgeben. Es bestand aus mehreren Gebäuden, darunter: (i) Principia (das Hauptquartier der Legion, in dem die Verwaltungsaufgaben erledigt und religiöse Zeremonien abgehalten wurden), (ii) Praetorium (das Wohnhaus des Kommandeurs der Legion), (iii) Kasernen (Unterkünfte für die Soldaten), sowie Thermen (öffentliche Bäder für die Legionäre, von denen einige Reste im heutigen Wien noch besichtigt werden können)"}, {"kategorie": "", "text": "Außerhalb des Lagers befand sich die Zivilsiedlung, in der Händler, Handwerker und die Familien der Soldaten lebten. Diese Siedlung entwickelte sich zu einem blühenden Handelsplatz"}, {"kategorie": "", "text": "Im Jahr 180 n. Chr. starb der römische Kaiser Mark Aurel in Vindobona während eines Feldzugs gegen die germanischen Stämme. Dieser Tod verbindet die Stadt mit einem bedeutenden historischen Ereignis des Römischen Reiches"}, {"kategorie": "", "text": "Mit dem allmählichen Zerfall des Römischen Reiches ab dem 4. Jahrhundert n. Chr. verlor Vindobona an Bedeutung. Um das Jahr 400 n. Chr. begannen die Römer, sich aus der Region zurückzuziehen, und die Stadt wurde schließlich im Laufe des 5. Jahrhunderts aufgegeben, als die germanischen Völker die römischen Provinzen besetzten"}, {"kategorie": "", "text": "Heute sind die Überreste von Vindobona in der Wiener Innenstadt verborgen, aber es gibt mehrere archäologische Funde und Gedenkstätten, die an die römische Vergangenheit erinnern. Zu den bekanntesten gehören: (i) Römische Ausgrabungen am [[Hohen]] Markt (hier können Überreste eines römischen Tribunenhauses besichtigt werden), (ii) [[Römermuseum]] Wien (bietet Einblicke in das Leben der Römer in Vindobona und zeigt archäologische Funde, darunter Waffen, Alltagsgegenstände und Bauwerke), sowie (iii) Römische Thermen am [[Michaelerplatz]] (hier sind Überreste eines römischen Badehauses zu sehen, die bei Bauarbeiten entdeckt wurden)."}]'::jsonb, ''),
  ('roemamuseum', 'Römamuseum', '', '', '', '', 'Römermuseum', '[{"kategorie": "allg.", "text": "\"Museum, das sich mit der römischen Vergangenheit der Stadt beschäftigt, insbesondere mit der Zeit, als das heutige Wien unter dem Namen [[Vindobona]] ein bedeutender Militärstützpunkt des Römischen Reiches war\""}, {"kategorie": "", "text": "Die römische Siedlung [[Vindobona]] war ein bedeutendes römisches Legionslager, das im 1. Jahrhundert n. Chr. gegründet wurde und bis ins 5. Jahrhundert bestand. Es diente vor allem der Sicherung der nördlichen Grenzen des Römischen Reiches entlang der Donau. Rund 6.000 Soldaten waren in Vindobona stationiert, und die angrenzende zivile Siedlung entwickelte sich zu einem wichtigen Handels- und Wirtschaftszentrum"}, {"kategorie": "", "text": "Das heutige Römermuseum befindet sich am [[Hohen]] Markt, einem der ältesten Plätze Wiens, wo viele archäologische Ausgrabungen stattfanden"}, {"kategorie": "", "text": "Es zeigt zahlreiche archäologische Funde, die in Wien und Umgebung entdeckt wurden, und vermittelt ein anschauliches Bild vom Leben in Vindobona.  4. Ein Highlight des Museums sind die Fundamente eines ehemaligen römischen Tribunenhauses, die direkt im Museum zu sehen sind. Diese Überreste sind ein Zeugnis der römischen Baukunst und ein bedeutendes Beispiel für die Infrastruktur eines Legionslagers"}, {"kategorie": "", "text": "Ansonsten umfassen die gezeigten Exponate (i) römische Alltagsgegenstände (Keramiken, Werkzeuge, Schmuck und Münzen, die das tägliche Leben der Soldaten und Zivilisten in Vindobona veranschaulichen), (ii) militärische Ausrüstung (Waffen, Rüstungen und Ausrüstungsgegenstände der römischen Soldaten), (iii) architektonische Überreste (Fundamente von Gebäuden wie das Tribunenhaus und Teile der römischen Thermen, die unter der heutigen Stadt gefunden wurden), sowie (iv) Modelle und Rekonstruktionen (Modelle von [[Vindobona]], die das Aussehen des römischen Lagers und der Zivilsiedlung zeigen)"}]'::jsonb, ''),
  ('kriminalmuseum', 'Kriminalmuseum', '', '', '', '', 'Kriminalmuseum', '[{"kategorie": "allg.", "text": "\"Spezialmuseum, das sich mit der Geschichte des Verbrechens und der Strafverfolgung in Wien und Österreich beschäftigt\""}, {"kategorie": "", "text": "Es befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]) in der [[Großen]] Sperlgasse und bietet einen umfassenden Einblick in die kriminalhistorische Entwicklung der Stadt, beginnend vom Mittelalter bis in die Gegenwart"}, {"kategorie": "", "text": "Das Museum ist einzigartig in Österreich und behandelt spektakuläre Kriminalfälle sowie die Entwicklung der Strafverfolgung und Justiz"}, {"kategorie": "", "text": "Das Wiener Kriminalmuseum ist in einem der ältesten Häuser Wiens untergebracht, einem Gebäude, das auf das 17. Jahrhundert zurückgeht. Ursprünglich war das Museum eine Sammlung von Exponaten, die in den 1890er Jahren von der Wiener Polizei zusammengetragen wurden, um Schulungen für Beamte zu unterstützen. Heute ist es ein öffentlich zugängliches Museum, das einen detaillierten Überblick über die düstere Seite der Wiener Geschichte gibt (Verbrechen im Mittelalter, Hexenverfolgungen, Bandenkriminalität im 18. und 19. Jahrhundert, bekannte Kriminalfälle der Neuzeit, sowie Grüdung und Entwicklung der Wiener Polizei)"}]'::jsonb, ''),
  ('zirkusmuseum', 'Zirkusmuseum', '', '', '', '', 'Zirkusmuseum', '[{"kategorie": "kurz für", "text": "\"Zirkus- und Clownmuseum Wien\" = eine Spezialsammlung in Wien, die sich der Geschichte des Zirkus, des Varietés und der Clownerie widmet\""}, {"kategorie": "", "text": "Das Museum befindet sich im am [[Ilgplatz]] im 2. Bezirk ([[Leopoldstadt]]) und ist einzigartig in Österreich, da es sich auf die Darstellung der kulturellen Entwicklung des Zirkuswesens konzentriert"}, {"kategorie": "", "text": "Es bietet einen umfassenden Überblick über die Kunst des Zirkus und die Rolle von Clowns, Artisten und Schaustellern in der Geschichte"}, {"kategorie": "", "text": "Das Zirkus- und Clownmuseum wurde von Heinz Scheuermann und Manfred Edlauer ins Leben gerufen, die beide eine große Leidenschaft für den Zirkus und seine Geschichte hatten. Die Sammlung des Museums begann als private Kollektion, wuchs jedoch im Laufe der Jahre erheblich an und wurde schließlich zu einem öffentlich zugänglichen Museum"}, {"kategorie": "", "text": "Die Leopoldstadt, in der sich das Museum befindet, hat eine enge historische Verbindung zum Zirkus und zum Schaustellerwesen, da sich hier früher zahlreiche Zirkusunternehmen und Varietétheater angesiedelt hatten"}, {"kategorie": "", "text": "Das Zirkusmuseum zeigt eine umfangreiche Sammlung von Zirkusmemorabilien und historischen Exponaten, die das Leben und die Arbeit im Zirkus dokumentieren. Zu den wichtigsten Ausstellungsstücken gehören: (i) Kostüme und Requisiten von Zirkuskünstlern und Clowns, (ii) Plakate, Programme und Flyer von berühmten Zirkusvorstellungen, die bis ins 19. Jahrhundert zurückreichen, (iii) Fotografien und Filme (historische Fotografien und Filmaufnahmen von Zirkusvorstellungen und berühmten Artisten), (iv) Clown-Memorabilia (Kostüme, Schminkutensilien und persönliche Gegenstände von Clowns), sowie (v) Modelle von Zirkusarenen und Miniaturzirkussen, die einen Einblick in die Welt des Zirkus geben"}, {"kategorie": "", "text": "Besondere Aufmerksamkeit wird in den Ausstellungen berühmten Zirkusfamilien und -künstlern wie der Familie Althoff oder Flick-Flack-Artisten gewidmet, die über Generationen hinweg die Zirkuskultur geprägt haben."}]'::jsonb, ''),
  ('ueuegplotz', 'Üügplotz', '', '', '', '', 'Ilgplatz', '[{"kategorie": "allg.", "text": "\"kleiner, historischer Platz im 2. Wiener Bezirk ([[Leopoldstadt]]) in der Nähe des [[Praters]]\""}, {"kategorie": "", "text": "Der Platz ist nach dem Wiener Kunsthistoriker August Ilg (1847-1896) benannt, der sich durch seine Forschungen und Beiträge zur Kunst- und Architekturgeschichte Wiens einen Namen gemacht hatte. Er wurde insbesondere für seine Arbeiten zur Architektur der Wiener Ringstraße geschätzt und trug maßgeblich zur Dokumentation und Erforschung der Wiener Kunstgeschichte bei. Außerdem arbeitete er als Mitarbeiter der \"Frankfurter Allgemeinen Zeitung\" und Kunstreferent der \"Presse\" und war Ehrenmitglied des Vereins zur Erhaltung der Kunstdenkmäler (1886)"}, {"kategorie": "", "text": "Eine der zentralen Attraktionen am Ilgplatz ist das Zirkus- und Clownmuseum (kurz [[Zirkusmuseum]] genannt), das die Geschichte des Zirkuswesens und der Clownerie in Wien und darüber hinaus beleuchtet. Das Museum beherbergt eine umfangreiche Sammlung an Zirkusmemorabilien, darunter Kostüme, Requisiten, historische Plakate und Fotografien."}]'::jsonb, ''),
  ('werdatoa', 'Werdatoa', '', '', '', '', 'Werdertor', '[{"kategorie": "allg.", "text": "\"eines der mittelalterlichen Stadttore der Wiener Stadtbefestigung im heutigen 1. Wiener Gemeindebezirk ([[Innere]] Stadt), nahe dem [[Donaukanal]]\""}, {"kategorie": "", "text": "Es war Teil der alten Stadtmauer, die Wien umgab, und spielte eine wichtige Rolle in der Verteidigung der Stadt. Das Tor diente als Zugang zur Stadt für Reisende und Händler, die von Norden oder über den Donaukanal nach Wien kamen"}, {"kategorie": "", "text": "Das alte Werdertor befand sich beim Ruprechtssteig und wurde im Mittelalter errichtet, vermutlich im 13. Jahrhundert, als Wien durch eine starke Stadtmauer geschützt wurde. Es war eines von mehreren Toren, die den Zugang zur Stadt regelten. Die Tore der Stadtmauer dienten nicht nur als Verteidigungsanlagen, sondern auch als Kontrollpunkte für den Handel und den Verkehr in die Stadt hinein und aus ihr heraus"}, {"kategorie": "", "text": "Der Name \"Werdertor\" leitet sich vermutlich von dem Wort \"Werder\" ab, das eine Flussinsel oder ein von Wasser umgebenes Gebiet bezeichnet. Heute erinnert die [[Werdertorgasse]], eine Straße im 1. Bezirk, an die historische Bedeutung dieses Tores"}, {"kategorie": "", "text": "Im Zuge der großen Stadterweiterungen und Modernisierungen Wiens im 19. Jahrhundert wurden viele der mittelalterlichen Befestigungsanlagen abgerissen, um Platz für neue Gebäude und Straßen zu schaffen. Auch das Werdertor wurde in dieser Zeit entfernt. Der Abriss war Teil der Umgestaltung Wiens zur modernen Großstadt, bei der auch die [[Ringstraße]] entstand und viele historische Bauwerke weichen mussten."}]'::jsonb, ''),
  ('werdatoagossn', 'Werdatoagossn', '', '', '', '', 'Werdertorgasse', '[{"kategorie": "allg.", "text": "\"historisch bedeutsame Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die sich in der Nähe des [[Donaukanals]] befindet\""}, {"kategorie": "", "text": "Sie verläuft zwischen dem [[Schottenring]] und dem [[Salzgries]] und liegt in einem historischen Teil der Wiener Innenstadt"}, {"kategorie": "", "text": "Die Straße ist nach dem ehemaligen [[Werdertor]] benannt, einem der mittelalterlichen Stadttore Wiens, das in der Nähe stand und Teil der historischen Wiener Stadtbefestigung war"}, {"kategorie": "", "text": "Die Gegend um die Werdertorgasse war im Mittelalter Teil der Wiener Vorstadt und lag nahe dem Donaukanal, einem wichtigen Handelsweg für die Stadt"}, {"kategorie": "", "text": "Die Werdertorgasse ist von repräsentativen Wohn- und Geschäftsgebäuden geprägt, die oft im Stil des [[Historismus]] oder des [[Jugendstils]] gehalten sind. In der Umgebung befinden sich mehrere bedeutende historische Gebäude und Institutionen, darunter die Alte [[Börse]] Wien und das Hotel Marriott, das sich in einem prächtigen Gebäude aus dem 19. Jahrhundert befindet."}]'::jsonb, ''),
  ('juudngossn', 'Juudngossn', '', '', '', '', 'Judengasse', '[{"kategorie": "allg.", "text": "\"historische Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die im mittelalterlichen Wien das Zentrum des jüdischen Viertels bildete\""}, {"kategorie": "", "text": "Sie liegt in unmittelbarer Nähe zum [[Judenplatz]], einem Ort von großer historischer und kultureller Bedeutung für die jüdische Gemeinde Wiens. Die Judengasse erinnert an das blühende jüdische Leben im mittelalterlichen Wien und ist eng mit der Geschichte und der Kultur der jüdischen Bevölkerung verbunden"}, {"kategorie": "", "text": "Die Judengasse entstand im Mittelalter, als sich ab dem 12. Jahrhundert jüdische Familien in Wien ansiedelten und ein eigenes Viertel in der Stadt bildeten. Dieses jüdische Viertel entwickelte sich rund um den Judenplatz und die Judengasse und war ein Zentrum des religiösen, sozialen und wirtschaftlichen Lebens der jüdischen Gemeinde in Wien. Hier befanden sich wichtige Gebäude wie die Synagoge, Schulen und Wohnhäuser bedeutender jüdischer Bürger"}, {"kategorie": "", "text": "Die jüdische Gemeinde in Wien erlebte bis zum frühen 15. Jahrhundert eine Blütezeit, bevor es 1420/21 im Rahmen der sogenannten Wiener Geserah zur Vertreibung und Ermordung der jüdischen Bevölkerung kam. Dabei wurde das Viertel zerstört, und viele der historischen Gebäude, einschließlich der Synagoge, wurden niedergerissen"}, {"kategorie": "", "text": "Obwohl das jüdische Viertel im Mittelalter stark zerstört wurde, blieb die Bezeichnung Judengasse erhalten und verweist bis heute auf das jüdische Erbe der Stadt. In unmittelbarer Nähe der Judengasse befindet sich das Jüdische Museum Wien, das die Geschichte der jüdischen Gemeinde in Wien und Österreich dokumentiert, sowie das Holocaust-Mahnmal am Judenplatz, das an die im Holocaust ermordeten Juden Österreichs erinnert."}]'::jsonb, ''),
  ('apollogossn', 'Apollogossn', '', '', '', '', 'Apollogasse', '[{"kategorie": "allg.", "text": "\"typische Wiener Stadtstraße im Zentrum des 6. Wiener Gemeindebezirks ([[Mariahilf]])\""}, {"kategorie": "", "text": "Sie liegt in einem urbanen und dicht besiedelten Gebiet und ist nach nach dem hier einst ansässigen vornehmen Vergnügungsetablissement \"Apollosaal\" benannt, dessen Namensgeber wiederum der griechische Gott Apollon ist, der Gott der Künste, Musik, Poesie und Heilung in der griechischen Mythologie"}, {"kategorie": "", "text": "Die Straße verbindet die Millergasse im Westen mit dem Neubaugürtel im Osten, einem Teil des Wiener Gürtels, der eine der wichtigsten Verkehrsachsen der Stadt ist"}, {"kategorie": "", "text": "In unmittelbarer Nähe der Apollogasse befindet sich das [[Haus]] des Meeres, eines der größten öffentlichen Aquarien Österreichs und eine der bekanntesten Attraktionen Wiens. Das Haus des Meeres ist in einem ehemaligen [[Flakturm]] aus dem Zweiten Weltkrieg untergebracht und liegt im [[Esterházypark]], der nur wenige Gehminuten von der Apollogasse entfernt ist."}]'::jsonb, ''),
  ('flaktuam', 'Flaktuam', '', '', '', '', 'Flakturm', '[{"kategorie": "allg.", "text": "\"großer, massiver Bunkerbau, der während des Zweiten Weltkriegs von den Nationalsozialisten errichtet wurde, um deutsche und österreichische Städte vor Luftangriffen zu schützen\""}, {"kategorie": "", "text": "Der Name \"Flakturm\" leitet sich von [[Flak]] ab, was eine Abkürzung für Flugabwehrkanone (Fliegerabwehrkanone) ist"}, {"kategorie": "", "text": "Diese Türme dienten primär als Luftverteidigungsanlagen, die mit schweren Flugabwehrgeschützen ausgestattet waren, um feindliche Flugzeuge abzuwehren"}, {"kategorie": "", "text": "In Wien gibt es sechs Flaktürme, die während des Zweiten Weltkriegs gebaut wurden. Diese befinden sich im [[Augarten]], [[Arenbergpark]] und [[Esterházypark]]"}, {"kategorie": "", "text": "Einer der bekanntesten Flaktürme ist der im [[Esterházypark]], der heute das [[Haus]] des Meeres beherbergt. Nach dem Krieg wurden die Türme nicht abgerissen, da ihre massive Bauweise einen Abriss extrem schwierig und teuer machen würde"}, {"kategorie": "", "text": "Einige Flaktürme sind heute als Denkmäler eingetragen und stehen unter Denkmalschutz, da sie als Zeugnisse der Kriegsgeschichte dienen."}]'::jsonb, ''),
  ('esterhazypark', 'Esterhazypark', '', '', '', '', 'Esterházypark', '[{"kategorie": "allg.", "text": "kleiner, öffentlicher Park im 6. Wiener Gemeindebezirk ([[Mariahilf]]), der vor allem durch den darin befindlichen [[Flakturm]], in dem heute das [[Haus]] des Meeres untergebracht ist, bekannt ist"}, {"kategorie": "", "text": "Der Park liegt in einem dicht besiedelten städtischen Gebiet und bietet den Anwohnern und Besuchern der Gegend einen grünen Erholungsraum"}, {"kategorie": "", "text": "Benannt ist der Park nach der ungarischen Adelsfamilie [[Esterházy]], die eine bedeutende Rolle in der Geschichte der [[Habsburgermonarchie]] spielte"}, {"kategorie": "", "text": "Der Esterházypark geht auf das Gartenpalais der Familie Albrechtsburg zurück, die hier 1695-1698 ein Sommergebäude samt Park errichten ließen. 1754 bis zu seinem Tod 1794 war die Anlage im Besitz von Staatskanzler Wenzel Anton Fürst Kaunitz, der hier mehrmals Umgestaltungen vornehmen ließ. Unter Nikolaus II. Fürst Esterházy erfuhr der Garten teilweise eine Umgestaltung zum Landschaftspark."}]'::jsonb, ''),
  ('arenbeagpark', 'Arenbeagpark', '', '', '', '', 'Arenbergpark', '[{"kategorie": "allg.", "text": "\"öffentliche Grünanlage im 3. Wiener Gemeindebezirk ([[Landstraße]]), die sich durch ihre zentrale Lage und ihre historische Bedeutung auszeichnet\""}, {"kategorie": "", "text": "Der Park ist vor allem bekannt für die beiden markanten [[Flaktürme]], die während des Zweiten Weltkriegs errichtet wurden und noch heute das Stadtbild des Parks prägen"}, {"kategorie": "", "text": "Die beiden Flaktürme im Arenbergpark, oft als Gefechtsturm und Leitturm bezeichnet, sind massive, betonierte Bauwerke, die während des Zweiten Weltkriegs als Flugabwehrbunker und Schutzräume dienten. Ihre Größe und Bauweise machen sie zu weithin sichtbaren Landmarken im Park und der umliegenden Gegend. Die Türme wurden nach dem Krieg nicht abgerissen, da dies aufgrund ihrer massiven Struktur als technisch und finanziell zu aufwändig galt"}, {"kategorie": "", "text": "Der \"G-Turm\" (Gefechtsturm) diente als Plattform für schwere Flugabwehrgeschütze und war Teil der Luftverteidigung der Stadt, während der \"L-Turm\" (Leitturm) der Feuerleitung und Koordination der Flugabwehr diente"}, {"kategorie": "", "text": "Heute stehen die Flaktürme unter Denkmalschutz, und es gibt immer wieder Diskussionen über eine mögliche Nachnutzung oder Umgestaltung der Türme. In einem der Türme wird derzeit Kunst gelagert, aber eine umfassende öffentliche Nutzung ist bisher nicht realisiert worden"}, {"kategorie": "", "text": "Ansonsten ist der Arenbergpark heute eine grüne Oase inmitten eines dicht besiedelten Stadtgebiets mit weiten Rasenflächen, Bäumen, Blumenbeeten, Spielplätzen und Sitzbänken, die zum Verweilen einladen."}]'::jsonb, ''),
  ('ratschkygossn', 'Ratschkygossn', '', '', '', '', 'Ratschkygasse', '[{"kategorie": "allg.", "text": "\"Straße im 12. Wiener Gemeindebezirk (Meidling), welche die Hohenbergstraße im Osten mit der Reschgasse im Westen verbindet\""}, {"kategorie": "", "text": "Die Ratschkygasse wurde im 19. Jahrhundert benannt, um den Schriftsteller Joseph Franz Ratschky zu ehren. Dieser war ein bedeutender Vertreter der Wiener Literatur und vor allem für seine humorvollen und teils satirischen Gedichte bekannt, die in der Spätphase der Aufklärung entstanden"}, {"kategorie": "", "text": "Ratschky begründete 1777 den Musenalmanach (der bis 1796 erschien), schrieb Theaterstücke, Gedichte und Satiren und war ständiger Gast in Kramers Kaffeehaus, das sich im Bereich der heutigen Ratschkygasse befand"}, {"kategorie": "", "text": "Die Ratschkygasse liegt in einem gut angebundenen, urbanen Gebiet, in unmittelbarer Nähe zur wichtigsten Einkaufsstraße des Bezirks, der [[Meidlinger]] Hauptstraße."}]'::jsonb, ''),
  ('gruenbeagschdrossn', 'Grünbeagschdrossn', '', '', '', '', 'Grünbergstraße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 12. Wiener Gemeindebezirk ([[Meidling]]), welche in nord-südlicher Richtung verläuft und das Wiental (B 1) über die [[Altmannsdorfer]] Straße mit der [[Südosttangente]] (A 23) bzw. der Süd Autobahn (A 2) verbindet"}, {"kategorie": "", "text": "Die Straße ist nach dem [[Grünen Berg]] benannt, einem Hügel zwischen dem 13. Wiener Gemeindebezirk ([[Hietzing]]) und dem 12. Wiener Gemeindebezirk ([[Meidling]])"}, {"kategorie": "", "text": "Seinen Namen erhielt der Berg durch Josef Freiherr von Hagenmüller zu Grünberg, einem Gerichtsadvokaten. Dieser erbaute um 1790 auf dem Hügel mehrere Häuser, die unter dem Namen Grünbergsiedlung bekannt wurden"}, {"kategorie": "", "text": "Die Grünbergstraße ist eine der wichtigsten Verbindungen in diesem Teil Wiens. Sie dient nicht nur dem lokalen Verkehr, sondern auch als Zufahrtsstraße für Touristen, die den Schönbrunner Schlosspark besuchen."}]'::jsonb, ''),
  ('barawitzkagossn', 'Barawitzkagossn', '', '', '', '', 'Barawitzkagasse', '[{"kategorie": "allg.", "text": "\"belebte Verkehrsstraße im 19. Wiener Gemeindebezirk ([[Döbling]]), genauer gesagt im Stadtteil [[Heiligenstadt]]\""}, {"kategorie": "", "text": "Sie befindet sich zwischen der [[Heiligenstädter]] Straße und der [[Döblinger]] Hauptstraße und ist nach Stephan Barawitzka (* 1808, † 1891) benannt, einem Gemeinderat von Oberdöbling und Fabrikanten, der in der Region eine bedeutende Rolle spielte"}, {"kategorie": "", "text": "Stephan Barawitzka war ein erfolgreicher Fabrikant und setzte sich als Gemeinderat von Oberdöbling stark für die Entwicklung der Region ein. Die Benennung der Gasse zu seinen Ehren erfolgte, um seine Verdienste um die Entwicklung und Modernisierung des heutigen Bezirks Döbling zu würdigen"}, {"kategorie": "", "text": "Die Barawitzkagasse ist gut an das öffentliche Verkehrsnetz angebunden. In der Nähe verlaufen Straßenbahn- und Buslinien, und die U-Bahn-Station Heiligenstadt (U4) ist ebenfalls gut erreichbar, was eine direkte Verbindung zum Wiener Stadtzentrum ermöglicht."}]'::jsonb, ''),
  ('arndtschdrossn', 'Arndtschdrossn', '', '', '', '', 'Arndtstraße', '[{"kategorie": "allg.", "text": "belebte Wohnstraße im 12. Wiener Gemeindebezirk ([[Meidling]]), welche die [[Meidlinger]] Hauptstraße (einer der belebtesten Einkaufsstraßen im 12. Bezirk) mit der [[Längenfeldgasse]] (einer weiteren bedeutenden Verkehrsachse des 12. Bezirks) verbindet"}, {"kategorie": "", "text": "Die Straße bildet die Südgrenze des ehemaligen Vororts [[Gaudenzdorf]] zu Untermeidling und des heutigen Zählbezirks Gaudenzdorf"}, {"kategorie": "", "text": "Sie ist nach dem deutschen Dichter und patriotischen Schriftsteller Ernst Moritz Arndt (1769–1860) benannt ist. Arndt war für seine politischen Schriften und Gedichte bekannt, in denen er die Freiheit und Einheit Deutschlands forderte"}, {"kategorie": "", "text": "Im Auftrag der Stadt Wien hat eine HistorikerInnen-Kommission die historische Bedeutung jener Persönlichkeiten, nach denen Wiener Straßen benannt sind, von 2011 bis 2013 untersucht sowie eine zeithistorische Kontextualisierung vorgenommen. Aufgrund der daraus gewonnenen Erkenntnisse zur historischen Einordnung von Ernst Moritz Arndt wurde der Straßenname als Fall mit demokratiepolitisch relevanten biographischen Lücken eingeordnet"}, {"kategorie": "", "text": "Kraft Beschluss des Gemeinderatsausschusses für Kultur und Wissenschaft heißt die Straße seither nach Ilse Arndt (* 5. Februar 1913, † Jänner 2003), Gastwirtin, Holocaust-Überlebende und Zeitzeugin."}]'::jsonb, ''),
  ('laenganfoeoedgossn', 'Länganföödgossn', '', '', '', '', 'Längenfeldgasse', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 12. Wiener Bezirk ([[Meidling]]), die in Süd-Nord-Richtung von der Stiegerbrücke über dem [[Wienfluss]] ansteigend bis zum [[Wienerberg]] verläuft\""}, {"kategorie": "", "text": "Sie ist seit 1894 nach der Wohltäterin Josepha Haas von Längenfeld-Pfalzheim benannt und hieß davor teilweise Stiegergasse"}, {"kategorie": "", "text": "Josephine Haas von Längenfeld-Pfalzheim (* 1782 Burglengenfeld, Pfalz, † 29. November 1846in Meidling/Wien)  war Philanthropin und Stifterin der Kinderbewahranstalt in Meidling, für die sie Beihilfen von Heiratsausstattungen für arme Mädchen aus Niederösterreich und Oberösterreich spendete"}, {"kategorie": "", "text": "Sie wurde zunächst am Schmelzer Friedhof begraben, aber nach dessen Erlöschen 1900 auf den [[Meidlinger]] Friedhof überführt"}, {"kategorie": "", "text": "Die nach ihr benannte Längenfeldgasse verbindet verschiedene Wohnviertel und Gewerbebereiche in den Bezirken [[Meidling]] und [[Rudolfsheim-Fünfhaus]]. Sie ist vor allem als Verkehrsstraße und durch die nahegelegene U-Bahn-Station bekannt, die viele Anwohner und Pendler aus benachbarten Bezirken anzieht. In den Seitenstraßen gibt es zahlreiche Wohngebäude, lokale Geschäfte und Bildungseinrichtungen, die das tägliche Leben der Anwohner prägen."}]'::jsonb, ''),
  ('haidaeckagossn', 'Haidäckagossn', '', '', '', '', 'Haidackergasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 12. Wiener Gemeindebezirk, die durch den [[Meidlinger]] Friedhof besondere Bedeutung erlangt hat\""}, {"kategorie": "", "text": "Der Friedhof ist 130.331 Quadratmeter groß, verfügt über rund 17.230 Grabstellen und besteht aus zwei Teilen, die durch die [[Eibesbrunnergasse]] getrennt werden, wo sich auch zwei weitere Eingänge befinden"}, {"kategorie": "", "text": "Die Haidackergasse liegt in einem ruhigen Wohnviertel, das überwiegend von Mehrfamilienhäusern geprägt ist. Durch den [[Meidlinger]] Friedhof, der ein bedeutendes historisches und kulturelles Erbe darstellt, ist die Haidackergasse ein zentraler Teil dieses Bezirks. Der Friedhof verleiht der Umgebung eine besondere Atmosphäre und zieht sowohl Anwohner als auch Besucher an, die ihre Angehörigen besuchen oder den historischen Charakter des Ortes schätzen."}]'::jsonb, ''),
  ('eibesbrunnagossn', 'Eibesbrunnagossn', '', '', '', '', 'Eibesbrunnergasse', '[{"kategorie": "allg.", "text": "\"Straße im 12. Wiener Bezirk ([[Meidling]]), die sich durch ihre Lage in einem vorwiegend gewerblich genutzten Gebiet auszeichnet\""}, {"kategorie": "", "text": "Sie verläuft vom Areal des [[Meidlinger]] Bahnhofs in Richtung Süden bis zur Straße [[Am]] Schöpfwerk"}, {"kategorie": "", "text": "Die Eibesbrunnergasse teilt zudem den [[Meidlinger]] Friedhof (einen der lältesten friedhöfe Wiens in zwei Teile und weist - neben der [[Haidackergasse]] - zwei weitere Friedhofseingänge auf"}, {"kategorie": "", "text": "Sie ist nach Michael Eybesbrunner (um 1371) und Ulrich Eybesbrunner (um 1442), beide Besitzer der historischen Flur Eglsee, benannt"}, {"kategorie": "", "text": "Heute ist die Eibesbrunnergasse eine funktionale Straße, die vor allem für die Gewerbebetriebe und Unternehmen in der Umgebung von Bedeutung ist."}]'::jsonb, '')
